def parse_ini(text: str) -> dict[str, dict[str, str]]:
    _VALID_NAME_CHARS = set('ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-')

    def is_name(s: str) -> bool:
        return bool(s) and all(c in _VALID_NAME_CHARS for c in s)

    sections = {}
    current_section = ""
    sections[current_section] = {}

    lines = text.split('\n')
    for line in lines:
        if line.endswith('\r'):
            line = line[:-1]
        line = line.strip(' \t')

        if not line or line[0] in (';', '#'):
            continue

        if line.startswith('[') and line.endswith(']'):
            sec_name = line[1:-1].strip(' \t')
            if not is_name(sec_name):
                raise ValueError(f"Invalid section name: {sec_name}")
            if sec_name not in sections:
                sections[sec_name] = {}
            current_section = sec_name
        elif '=' in line:
            key, value = line.split('=', 1)
            key = key.strip(' \t')
            if not is_name(key):
                raise ValueError(f"Invalid key name: {key}")
            key_lower = key.lower()
            if key_lower in sections[current_section]:
                raise ValueError(f"Duplicate key: {key}")
            sections[current_section][key_lower] = value.strip(' \t')
        else:
            raise ValueError(f"Invalid line: {line}")

    if not sections[""]:
        del sections[""]

    def expand(value: str, current_section: str, current_key: str, sections: dict, expanding: set) -> str:
        result = []
        i = 0
        while i < len(value):
            if value[i] == '$':
                if i + 1 >= len(value):
                    raise ValueError("Invalid reference at end of value")
                if value[i+1] == '$':
                    result.append('$')
                    i += 2
                elif value[i+1] == '{':
                    close = value.find('}', i+2)
                    if close == -1:
                        raise ValueError("Missing closing }")
                    ref = value[i+2:close]
                    if ':' in ref:
                        sec, key = ref.split(':', 1)
                    else:
                        sec, key = current_section, ref

                    if sec != "" and not is_name(sec):
                        raise ValueError(f"Invalid section name in reference: {sec}")
                    if not is_name(key):
                        raise ValueError(f"Invalid key name in reference: {key}")

                    if sec not in sections:
                        raise ValueError(f"Section {sec} not found")

                    sec_data = sections[sec]
                    matched_key = None
                    for k in sec_data:
                        if k == key.lower():
                            matched_key = k
                            break
                    if matched_key is None:
                        raise ValueError(f"Key {key} not found in section {sec}")

                    if (sec, matched_key) in expanding:
                        raise ValueError("Reference cycle detected")

                    expanding.add((sec, matched_key))
                    expanded = expand(sec_data[matched_key], sec, matched_key, sections, expanding)
                    expanding.remove((sec, matched_key))

                    result.append(expanded)
                    i = close + 1
                else:
                    raise ValueError("Invalid reference")
            else:
                result.append(value[i])
                i += 1
        return ''.join(result)

    result = {}
    for sec, data in sections.items():
        result[sec] = {}
        for key, value in data.items():
            expanding = set()
            expanding.add((sec, key))
            result[sec][key] = expand(value, sec, key, sections, expanding)

    return result

