def forth(src: str) -> list[int]:
    tokens = [t.lower() for t in src.split()]

    dict_def = {}
    stack = []

    def exec_builtin(name, stk):
        if name == '+':
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            stk.append(a + b)
        elif name == '-':
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            stk.append(a - b)
        elif name == '*':
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            stk.append(a * b)
        elif name == '/':
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            if b == 0: raise ZeroDivisionError
            stk.append(a // b)
        elif name == 'mod':
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            if b == 0: raise ZeroDivisionError
            stk.append(a % b)
        elif name == '/mod':
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            if b == 0: raise ZeroDivisionError
            stk.append(a % b)
            stk.append(a // b)
        elif name == 'negate':
            if len(stk) < 1: raise ValueError("stack underflow")
            stk.append(-stk.pop())
        elif name == 'abs':
            if len(stk) < 1: raise ValueError("stack underflow")
            stk.append(abs(stk.pop()))
        elif name == 'dup':
            if len(stk) < 1: raise ValueError("stack underflow")
            stk.append(stk[-1])
        elif name == 'drop':
            if len(stk) < 1: raise ValueError("stack underflow")
            stk.pop()
        elif name == 'swap':
            if len(stk) < 2: raise ValueError("stack underflow")
            stk[-2], stk[-1] = stk[-1], stk[-2]
        elif name == 'over':
            if len(stk) < 2: raise ValueError("stack underflow")
            stk.append(stk[-2])
        elif name == 'rot':
            if len(stk) < 3: raise ValueError("stack underflow")
            stk[-3], stk[-2], stk[-1] = stk[-2], stk[-1], stk[-3]
        elif name in ('=', '<', '>'):
            if len(stk) < 2: raise ValueError("stack underflow")
            b, a = stk.pop(), stk.pop()
            if name == '=': res = (a == b)
            elif name == '<': res = (a < b)
            else: res = (a > b)
            stk.append(-1 if res else 0)
        else:
            raise ValueError(f"unknown builtin: {name}")

    def resolve_word(tok):
        if re.match(r'^-?\d+$', tok):
            return ('lit', int(tok))
        if tok in dict_def:
            return ('user', dict_def[tok])
        if tok in ('+', '-', '*', '/', 'mod', '/mod', 'negate', 'abs',
                   'dup', 'drop', 'swap', 'over', 'rot', '=', '<', '>'):
            return ('builtin', tok)
        if tok in ('if', 'else', 'then', 'begin', 'until'):
            raise ValueError(f"control word {tok} used outside definition or unknown")
        raise ValueError(f"unknown word: {tok}")

    def append_to_current(item, instructions, ctrl_stack):
        if not ctrl_stack:
            instructions.append(item)
        else:
            top = ctrl_stack[-1]
            if top['type'] == 'if':
                if top['state'] == 'b1':
                    top['b1'].append(item)
                else:
                    top['b2'].append(item)
            else:
                top['body'].append(item)

    def compile_body(body_tokens):
        instructions = []
        ctrl_stack = []

        for tok in body_tokens:
            if tok == 'if':
                ctrl_stack.append({'type': 'if', 'b1': [], 'b2': [], 'state': 'b1'})
            elif tok == 'else':
                if not ctrl_stack or ctrl_stack[-1]['type'] != 'if':
                    raise ValueError("misplaced else")
                ctrl_stack[-1]['state'] = 'b2'
            elif tok == 'then':
                if not ctrl_stack or ctrl_stack[-1]['type'] != 'if':
                    raise ValueError("misplaced then")
                frame = ctrl_stack.pop()
                instr = ('if', frame['b1'], frame['b2'])
                append_to_current(instr, instructions, ctrl_stack)
            elif tok == 'begin':
                ctrl_stack.append({'type': 'begin', 'body': []})
            elif tok == 'until':
                if not ctrl_stack or ctrl_stack[-1]['type'] != 'begin':
                    raise ValueError("misplaced until")
                frame = ctrl_stack.pop()
                instr = ('begin', frame['body'])
                append_to_current(instr, instructions, ctrl_stack)
            else:
                compiled = resolve_word(tok)
                append_to_current(compiled, instructions, ctrl_stack)

        if ctrl_stack:
            raise ValueError("unbalanced control words")
        return instructions

    def execute_code(code, stk):
        for instr in code:
            if instr[0] == 'lit':
                stk.append(instr[1])
            elif instr[0] == 'user':
                execute_code(instr[1], stk)
            elif instr[0] == 'builtin':
                exec_builtin(instr[1], stk)
            elif instr[0] == 'if':
                if len(stk) < 1: raise ValueError("stack underflow")
                flag = stk.pop()
                if flag != 0:
                    execute_code(instr[1], stk)
                else:
                    execute_code(instr[2], stk)
            elif instr[0] == 'begin':
                while True:
                    execute_code(instr[1], stk)
                    if len(stk) < 1: raise ValueError("stack underflow")
                    flag = stk.pop()
                    if flag != 0:
                        break

    in_def = False
    def_name = None
    def_body_tokens = []

    i = 0
    while i < len(tokens):
        tok = tokens[i]
        if in_def:
            if tok == ';':
                if def_name not in dict_def:
                    raise ValueError(f"recursive definition of undefined word: {def_name}")
                compiled = compile_body(def_body_tokens)
                dict_def[def_name] = compiled
                in_def = False
                def_name = None
                def_body_tokens = []
            elif tok == ':':
                raise ValueError("nested definition not allowed")
            else:
                def_body_tokens.append(tok)
        else:
            if tok == ':':
                if i + 1 >= len(tokens):
                    raise ValueError("missing name after colon")
                i += 1
                def_name = tokens[i]
                if re.match(r'^-?\d+$', def_name):
                    raise ValueError("colon followed by number literal")
                in_def = True
                def_body_tokens = []
            elif tok == ';':
                raise ValueError("semicolon outside definition")
            else:
                if tok in ('if', 'else', 'then', 'begin', 'until'):
                    raise ValueError("control word outside definition")
                if tok in dict_def:
                    execute_code(dict_def[tok], stack)
                elif tok in ('+', '-', '*', '/', 'mod', '/mod', 'negate', 'abs',
                             'dup', 'drop', 'swap', 'over', 'rot', '=', '<', '>'):
                    exec_builtin(tok, stack)
                else:
                    raise ValueError(f"unknown word: {tok}")
        i += 1

    if in_def:
        raise ValueError("missing semicolon at end of source")

    return stack

