                    elif bw == 'begin': 
                        begin_depth += 1
                        def_body.append('begin')
                    elif bw == 'else':
                        if if_depth == 0: raise ValueError("else without if")
                        def_body.append('else')
                    elif bw == 'then':
                        if if_depth > 0: if_depth -= 1
                        elif begin_depth > 0: begin_depth -= 1
                        else: raise ValueError("then without if or begin")
                        def_body.append('then')
                    elif bw == 'until':
                        if begin_depth == 0: raise ValueError("until without begin")
                        begin_depth -= 1
                        def_body.append('until')
                elif is_num(bw):
                    def_body.append(int(bw))
                elif bw in dictionary:
                    if bw == current_name:
                        if current_name in dictionary:
                            def_body.extend(dictionary[bw])
                        else:
                            raise ValueError(f"undefined word in definition: {bw}")
                    else:
                        def_body.extend(dictionary[bw])
                elif bw in builtins:
                    def_body.append(('builtin', bw))
                else:
                    raise ValueError(f"undefined word in definition: {bw}")
                i += 1

            if defining: raise ValueError("missing ';'")
        elif defining:
            raise ValueError("syntax error")
        else:
            if w in control_words: raise ValueError("control word outside body")
            if w in dictionary:
                run(dictionary[w], stack)
            elif w in builtins:
                apply_builtin(w, stack)
            elif is_num(w):
                stack.append(int(w))
            else:
                raise ValueError(f"unknown word: {w}")
            i += 1

    if defining: raise ValueError("missing ';'")
    return stack

import sys

def forth(src: str) -> list[int]:
    # Split source into words
    tokens = src.split()

    # Data structures
    stack = []
    dict_ = {} # name -> list of nodes

    # Built-in functions and signatures
    # Signatures: (function, inputs, outputs)
    # Inputs/Outputs are counts.

    def add(a, b): return a + b
    def sub(a, b): return a - b
    def mul(a, b): return a * b

    def floor_div(a, b): 
        if b == 0: raise ZeroDivisionError
        return a // b

    def mod(a, b): 
        if b == 0: raise ZeroDivisionError
        return a % b

    def divmod_res(a, b):
        if b == 0: raise ZeroDivisionError
        return (a % b, a // b)

    def negate(a): return -a
    def abs_val(a): return abs(a)
    def dup(a): return (a, a)
    def drop(a): return ()
    def swap(a, b): return (b, a)
    def over(a, b): return (a, b, a)
    def rot(a, b, c): return (b, c, a)

    def eq(a, b): return -1 if a == b else 0
    def lt(a, b): return -1 if a < b else 0
    def gt(a, b): return -1 if a > b else 0

    builtins = {
        '+': (add, 2, 1),
        '-': (sub, 2, 1),
        '*': (mul, 2, 1),
        '/': (floor_div, 2, 1),
        'mod': (mod, 2, 1),
        '/mod': (divmod_res, 2, 2),
        'negate': (negate, 1, 1),
        'abs': (abs_val, 1, 1),
        'dup': (dup, 1, 2),
        'drop': (drop, 1, 0),
        'swap': (swap, 2, 2),
        'over': (over, 2, 3),
        'rot': (rot, 3, 3),
        '=': (eq, 2, 1),
        '<': (lt, 2, 1),
        '>': (gt, 2, 1),
    }

    control_words = {'if', 'else', 'then', 'begin', 'until'}

    def is_number(s):
        if not s: return False
        if s.startswith('-'):
            if len(s) == 1: return False
            return s[1:].isdigit()
        return s.isdigit()

    # Node types in compiled lists:
    # int: literal
    # tuple (func, req, ret): builtin
    # list: user-defined word (inlined)
    # tuple ('if', then_nodes, else_nodes): if structure
    # tuple ('until', body_nodes): until structure

    def compile_word(word):
        # Check if number literal
        if is_number(word):
            return int(word)

        # Check control words (should not be compiled into body, handled by parser)
        if word in control_words:
            raise ValueError(f"Control word {word} used in body")

        # Check user dictionary
        if word in dict_:
            return dict_[word]

        # Check builtins
        if word in builtins:
            return builtins[word]

        # Unknown
        raise ValueError(f"Unknown word: {word}")

    def execute_list(nodes, stack):
        for node in nodes:
            if isinstance(node, int):
                stack.append(node)
            elif isinstance(node, tuple) and len(node) == 3 and callable(node[0]):
                # Builtin
                func, req, ret = node
                if len(stack) < req:
                    raise ValueError("Stack underflow")
                args = [stack.pop() for _ in range(req)]
                args.reverse()
                res = func(*args)
                if isinstance(res, tuple):
                    stack.extend(res)
                else:
                    stack.append(res)
            elif isinstance(node, list):
                # User word
                execute_list(node, stack)
            elif isinstance(node, tuple) and len(node) == 3 and node[0] == 'if':
                _, then_nodes, else_nodes = node
                if len(stack) < 1:
                    raise ValueError("Stack underflow")
                flag = stack.pop()
                if flag != 0:
                    execute_list(then_nodes, stack)
                else:
                    execute_list(else_nodes, stack)
            elif isinstance(node, tuple) and len(node) == 2 and node[0] == 'until':
                _, body_nodes = node
                while True:
                    execute_list(body_nodes, stack)
                    if len(stack) < 1:
                        raise ValueError("Stack underflow")
                    flag = stack.pop()
                    if flag != 0:
                        break
            else:
                raise ValueError(f"Unknown node: {node}")

    # Parsing and Execution State
    compiling = False
    comp_name = None
    comp_stack = [] # Stack of lists for nested blocks
    control_stack = [] # Stack of control structures

    # Helper to get current list
    def current_list():
        if not comp_stack:
            return []
        return comp_stack[-1]

    i = 0
    while i < len(tokens):
        word = tokens[i]

        if not compiling:
            # Top level execution
            if word == ':':
                # Start definition
                if i + 1 >= len(tokens):
                    raise ValueError("':' with no name after it")
                i += 1
                name = tokens[i]
                if is_number(name):
                    raise ValueError("Name cannot be a number literal")
                if name in control_words:
                    raise ValueError("Name cannot be a control word")

                # Check if name is defined for early binding of self-reference?
                # Prompt: "inside its own body name means its previous definition"
                # So we look it up now.

                compiling = True
                comp_name = name
                comp_stack = [[]] # Root list for body
                control_stack = []
                i += 1
                continue

            # Execute word
            if word in control_words:
                raise ValueError("Control words outside a body")

            code = compile_word(word)

            if isinstance(code, int):
                stack.append(code)
            elif isinstance(code, tuple) and len(code) == 3 and callable(code[0]):
                # Builtin
                func, req, ret = code
                if len(stack) < req:
                    raise ValueError("Stack underflow")
                args = [stack.pop() for _ in range(req)]
                args.reverse()
                res = func(*args)
                if isinstance(res, tuple):
                    stack.extend(res)
                else:
                    stack.append(res)
            elif isinstance(code, list):
                # Executing a compiled word (inlined)
                execute_list(code, stack)
            else:
                raise ValueError(f"Unknown word: {word}")

        else:
            # Inside definition body
            if word == ';':
                # End definition
                if comp_stack or control_stack:
                    raise ValueError("Unbalanced control words")

                # Add to dictionary
                dict_[comp_name] = comp_stack[0]
                compiling = False
                comp_name = None
                comp_stack = []
                control_stack = []
                i += 1
                continue

            if word == ':':
                raise ValueError("':' inside a body")

            # Parse word
            if word in control_words:
                if word == 'if':
                    then_list = []
                    else_list = []
                    parent_list = comp_stack[-1]
                    control_stack.append({'type': 'if', 'then': then_list, 'else': else_list, 'parent': parent_list})
                    comp_stack.append(then_list)

                elif word == 'else':
                    if not control_stack or control_stack[-1]['type'] != 'if':
                        raise ValueError("Misplaced 'else'")
                    ctx = control_stack[-1]
                    comp_stack.append(ctx['else'])

                elif word == 'then':
                    if not control_stack or control_stack[-1]['type'] != 'if':
                        raise ValueError("Misplaced 'then'")
                    ctx = control_stack.pop()
                    if_node = ('if', ctx['then'], ctx['else'])
                    ctx['parent'].append(if_node)
                    comp_stack.pop()

                elif word == 'begin':
                    body_list = []
                    parent_list = comp_stack[-1]
                    control_stack.append({'type': 'begin', 'body': body_list, 'parent': parent_list})
                    comp_stack.append(body_list)

                elif word == 'until':
                    if not control_stack or control_stack[-1]['type'] != 'begin':
                        raise ValueError("Misplaced 'until'")
                    ctx = control_stack.pop()
                    until_node = ('until', ctx['body'])
                    ctx['parent'].append(until_node)
                    comp_stack.pop()

                else:
                    raise ValueError(f"Unknown control word: {word}")

            else:
                # Regular word or literal
                node = compile_word(word)
                current_list().append(node)

        i += 1

    if compiling:
        raise ValueError("Definition missing ';'")

    return stack

