def forth(src: str) -> list[int]:
    tokens = src.lower().split()
    defs = {}

    # Built-in operations
    def _add(s): a, b = s.pop(), s.pop(); s.append(a + b)
    def _sub(s): a, b = s.pop(), s.pop(); s.append(b - a)
    def _mul(s): a, b = s.pop(), s.pop(); s.append(a * b)
    def _div(s): a, b = s.pop(), s.pop(); s.append(b // a)
    def _mod(s): a, b = s.pop(), s.pop(); s.append(b % a)
    def _moddiv(s): a, b = s.pop(), s.pop(); s.append(b % a); s.append(b // a)
    def _negate(s): s.append(-s.pop())
    def _abs(s): s.append(abs(s.pop()))
    def _dup(s): a = s.pop(); s.append(a); s.append(a)
    def _drop(s): s.pop()
    def _swap(s): a, b = s.pop(), s.pop(); s.append(a); s.append(b)
    def _over(s): a, b = s.pop(), s.pop(); s.append(b); s.append(a); s.append(b)
    def _rot(s): a, b, c = s.pop(), s.pop(), s.pop(); s.append(b); s.append(c); s.append(a)
    def _eq(s): a, b = s.pop(), s.pop(); s.append(-1 if a == b else 0)
    def _lt(s): a, b = s.pop(), s.pop(); s.append(-1 if a < b else 0)
    def _gt(s): a, b = s.pop(), s.pop(); s.append(-1 if a > b else 0)

    builtins = {
        '+': _add, '-': _sub, '*': _mul, '/': _div, 'mod': _mod,
        '/mod': _moddiv, 'negate': _negate, 'abs': _abs, 'dup': _dup,
        'drop': _drop, 'swap': _swap, 'over': _over, 'rot': _rot,
        '=': _eq, '<': _lt, '>': _gt
    }

    control_words = {'if', 'else', 'then', 'begin', 'until'}
    num_pat = re.compile(r'^-?\d+$')

    def resolve_word(word):
        if word in defs:
            return ('call', defs[word])
        if word in builtins:
            return ('call', builtins[word])
        if num_pat.match(word):
            return ('lit', int(word))
        raise ValueError(f"Unknown word: {word}")

    def execute(instrs, stack):
        for instr in instrs:
            kind = instr[0]
            if kind == 'lit':
                stack.append(instr[1])
            elif kind == 'call':
                instr[1](stack)
            elif kind == 'if':
                then_b, else_b = instr[1], instr[2]
                flag = stack.pop()
                if flag != 0:
                    execute(then_b, stack)
                else:
                    execute(else_b, stack)
            elif kind == 'begin':
                body = instr[1]
                while True:
                    execute(body, stack)
                    flag = stack.pop()
                    if flag != 0:
                        break

    i = 0
    n = len(tokens)
    top_level = []

    while i < n:
        tok = tokens[i]
        if tok == ':':
            i += 1
            if i >= n:
                raise ValueError("':' with no name")
            name = tokens[i]
            i += 1
            if num_pat.match(name):
                raise ValueError("Name cannot be a number literal")

            ctx_stack = [{'type': 'root', 'items': []}]
            while i < n:
                tok = tokens[i]
                if tok == ';':
                    i += 1
                    break
                if tok == ':':
                    raise ValueError("':' inside body")
                if tok == 'if':
                    ctx_stack.append({'type': 'if_then', 'then': [], 'else': None})
                elif tok == 'else':
                    ctx = ctx_stack[-1]
                    if ctx['type'] != 'if_then':
                        raise ValueError("Misplaced 'else'")
                    ctx['type'] = 'if_else'
                    ctx['else'] = []
                elif tok == 'then':
                    ctx = ctx_stack.pop()
                    if ctx['type'] not in ('if_then', 'if_else'):
                        raise ValueError("Misplaced 'then'")
                    if ctx['type'] == 'if_then':
                        ctx['type'] = 'if_else'
                        ctx['else'] = []
                    ctx_stack[-1]['items'].append(('if', ctx['then'], ctx['else']))
                elif tok == 'begin':
                    ctx_stack.append({'type': 'begin', 'body': []})
                elif tok == 'until':
                    ctx = ctx_stack.pop()
                    if ctx['type'] != 'begin':
                        raise ValueError("Misplaced 'until'")
                    ctx_stack[-1]['items'].append(('begin', ctx['body']))
                else:
                    resolved = resolve_word(tok)
                    ctx_stack[-1]['items'].append(resolved)
                i += 1

            if i >= n:
                raise ValueError("Missing ';'")
            if len(ctx_stack) > 1 or ctx_stack[0]['type'] != 'root':
                raise ValueError("Unbalanced control words")
            top_level.append(('def', name, ctx_stack[0]['items']))

        elif tok in control_words:
            raise ValueError("Control word outside body")
        elif tok == ';':
            raise ValueError("';' outside body")
        else:
            resolved = resolve_word(tok)
            top_level.append(('run', resolved))
            i += 1

    stack = []
    for item in top_level:
        if item[0] == 'def':
            defs[item[1]] = item[2]
        else:
            execute([item[1]], stack)

    return stack

