def normalize_url(url: str) -> str:
    # 1. Split
    if "://" not in url:
        raise ValueError("Missing ://")
    scheme_end = url.index("://")
    scheme = url[:scheme_end]
    if not scheme:
        raise ValueError("Empty scheme")
    if not (scheme[0].isascii() and scheme[0].isalpha()):
        raise ValueError("Scheme must start with ASCII letter")
    for c in scheme[1:]:
        if not (c.isascii() and (c.isalnum() or c in "+-.")):
            raise ValueError("Invalid scheme character")
    scheme = scheme.lower()

    rest = url[scheme_end + 3:]

    # Find authority, path, query, fragment boundaries
    first_slash = rest.find("/")
    first_q = rest.find("?")
    first_hash = rest.find("#")

    auth_end = len(rest)
    for idx in [first_slash, first_q, first_hash]:
        if idx != -1 and idx < auth_end:
            auth_end = idx
    authority = rest[:auth_end]

    path = ""
    query = ""
    fragment = ""

    after_auth = rest[auth_end:]
    if after_auth.startswith("/"):
        path = after_auth[1:]
        next_q = rest.find("?", auth_end + 1)
        next_hash = rest.find("#", auth_end + 1)
        if next_q != -1:
            if next_hash != -1 and next_hash < next_q:
                query = ""
                fragment = rest[next_hash+1:]
            else:
                query = rest[next_q+1:]
                if next_hash != -1:
                    fragment = rest[next_hash+1:]
    elif after_auth.startswith("?"):
        query = after_auth[1:]
        next_hash = rest.find("#", auth_end + 1)
        if next_hash != -1:
            fragment = rest[next_hash+1:]
    elif after_auth.startswith("#"):
        fragment = after_auth[1:]

    # 2. Authority
    userinfo = ""
    host = ""
    port = ""

    at_idx = authority.rfind("@")
    if at_idx != -1:
        userinfo = authority[:at_idx]
        authority = authority[at_idx+1:]

    colon_idx = authority.find(":")
    if colon_idx != -1:
        host = authority[:colon_idx]
        port = authority[colon_idx+1:]
    else:
        host = authority

    if not host:
        raise ValueError("Empty host")
    for c in host:
        if not (c.isascii() and (c.isalnum() or c in ".-")):
            raise ValueError("Invalid host character")
    host = host.lower()

    if port:
        if not port.isdigit():
            raise ValueError("Invalid port")
        port_int = int(port)
        if port_int > 65535:
            raise ValueError("Port out of range")
        port = str(port_int)
        if scheme in ("http", "ws") and port == "80":
            port = ""
        elif scheme in ("https", "wss") and port == "443":
            port = ""
        elif scheme == "ftp" and port == "21":
            port = ""

    # 3. Percent-encoding
    def percent_encode(s: str) -> str:
        unreserved = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")
        exempt = set("!$&'()*+,;=:@/?")
        res = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '%':
                if i + 2 >= n:
                    raise ValueError("Invalid percent encoding")
                hex_digits = s[i+1:i+3]
                if not all(ch in "0123456789ABCDEFabcdef" for ch in hex_digits):
                    raise ValueError("Invalid hex digits")
                hex_digits = hex_digits.upper()
                byte_val = int(hex_digits, 16)
                char = chr(byte_val)
                if char in unreserved:
                    res.append(char)
                else:
                    res.append(f"%{hex_digits}")
                i += 3
            elif c in unreserved or c in exempt:
                res.append(c)
                i += 1
            else:
                utf8_bytes = c.encode('utf-8')
                for b in utf8_bytes:
                    res.append(f"%{b:02X}")
                i += 1
        return "".join(res)

    userinfo = percent_encode(userinfo)
    path = percent_encode(path)
    query = percent_encode(query)
    fragment = percent_encode(fragment)

    # 4. Dot segments
    def remove_dot_segments(path_str: str) -> str:
        if not path_str:
            return "/"
        inp = path_str
        output = []
        while inp:
            if inp.startswith("../"):
                inp = inp[3:]
            elif inp.startswith("./"):
                inp = inp[2:]
            elif inp.startswith("/./"):
                inp = "/" + inp[3:]
            elif inp == "/.":
                inp = "/"
            elif inp.startswith("/../"):
                inp = "/" + inp[4:]
                if output:
                    output.pop()
            elif inp == "/..":
                inp = "/"
                if output:
                    output.pop()
            elif inp in (".", ".."):
                inp = ""
            else:
                if inp.startswith("/"):
                    next_slash = inp.find("/", 1)
                    if next_slash == -1:
                        next_slash = len(inp)
                else:
                    next_slash = inp.find("/")
                    if next_slash == -1:
                        next_slash = len(inp)
                output.append(inp[:next_slash])
                inp = inp[next_slash:]
        return "".join(output)

    path = remove_dot_segments(path)

    # 5. Empty query/fragment
    query_part = f"?{query}" if query else ""
    fragment_part = f"#{fragment}" if fragment else ""

    # Authority parts
    auth_part = ""
    if userinfo:
        auth_part += f"{userinfo}@"
    auth_part += host
    if port:
        auth_part += f":{port}"

    return f"{scheme}://{auth_part}{path}{query_part}{fragment_part}"

def normalize_url(url: str) -> str:
    # 1. Split
    if "://" not in url:
        raise ValueError("Missing ://")
    scheme_end = url.index("://")
    scheme = url[:scheme_end]
    if not scheme:
        raise ValueError("Empty scheme")
    if not (scheme[0].isascii() and scheme[0].isalpha()):
        raise ValueError("Scheme must start with ASCII letter")
    for c in scheme[1:]:
        if not (c.isascii() and (c.isalnum() or c in "+-.")):
            raise ValueError("Invalid scheme character")
    scheme = scheme.lower()

    rest = url[scheme_end + 3:]

    # Find boundaries for authority, path, query, fragment
    # Authority ends at first '/', '?', or '#'
    first_slash = rest.find("/")
    first_q = rest.find("?")
    first_hash = rest.find("#")

    auth_end = len(rest)
    for idx in [first_slash, first_q, first_hash]:
        if idx != -1 and idx < auth_end:
            auth_end = idx

    authority = rest[:auth_end]
    remainder = rest[auth_end:]

    path = ""
    query = ""
    fragment = ""

    # Parse remainder to extract path, query, fragment
    if remainder.startswith("/"):
        # Path starts with /
        # Path ends at first '?' or '#'
        idx_q = remainder.find("?", 1)
        idx_hash = remainder.find("#", 1)

        path_end = len(remainder)
        if idx_q != -1:
            path_end = min(path_end, idx_q)
        if idx_hash != -1:
            path_end = min(path_end, idx_hash)

        path = remainder[:path_end]
        after_path = remainder[path_end:]

        if after_path.startswith("?"):
            q_content = after_path[1:]
            hash_idx = q_content.find("#")
            if hash_idx != -1:
                query = q_content[:hash_idx]
                fragment = q_content[hash_idx+1:]
            else:
                query = q_content
        elif after_path.startswith("#"):
            fragment = after_path[1:]

    elif remainder.startswith("?"):
        # No path
        q_content = remainder[1:]
        hash_idx = q_content.find("#")
        if hash_idx != -1:
            query = q_content[:hash_idx]
            fragment = q_content[hash_idx+1:]
        else:
            query = q_content

    elif remainder.startswith("#"):
        # No path, no query
        fragment = remainder[1:]

    # 2. Authority parsing
    userinfo = ""
    host = ""
    port = ""

    at_idx = authority.rfind("@")
    if at_idx != -1:
        userinfo = authority[:at_idx]
        authority = authority[at_idx+1:]

    colon_idx = authority.find(":")
    if colon_idx != -1:
        host = authority[:colon_idx]
        port = authority[colon_idx+1:]
    else:
        host = authority

    if not host:
        raise ValueError("Empty host")
    for c in host:
        if not (c.isascii() and (c.isalnum() or c in ".-")):
            raise ValueError("Invalid host character")
    host = host.lower()

    if port:
        if not port.isdigit():
            raise ValueError("Invalid port")
        port_int = int(port)
        if port_int > 65535:
            raise ValueError("Port out of range")
        port = str(port_int)
        if scheme in ("http", "ws") and port == "80":
            port = ""
        elif scheme in ("https", "wss") and port == "443":
            port = ""
        elif scheme == "ftp" and port == "21":
            port = ""

    # 3. Percent-encoding
    def percent_encode(s: str) -> str:
        unreserved = set("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~")
        exempt = set("!$&'()*+,;=:@/?")
        res = []
        i = 0
        n = len(s)
        while i < n:
            c = s[i]
            if c == '%':
                if i + 2 >= n:
                    raise ValueError("Invalid percent encoding")
                hex_digits = s[i+1:i+3]
                if not all(ch in "0123456789ABCDEFabcdef" for ch in hex_digits):
                    raise ValueError("Invalid hex digits")
                hex_digits = hex_digits.upper()
                byte_val = int(hex_digits, 16)
                char = chr(byte_val)
                if char in unreserved:
                    res.append(char)
                else:
                    res.append(f"%{hex_digits}")
                i += 3
            elif c in unreserved or c in exempt:
                res.append(c)
                i += 1
            else:
                utf8_bytes = c.encode('utf-8')
                for b in utf8_bytes:
                    res.append(f"%{b:02X}")
                i += 1
        return "".join(res)

    userinfo = percent_encode(userinfo)
    path = percent_encode(path)
    query = percent_encode(query)
    fragment = percent_encode(fragment)

    # 4. Dot segments
    def remove_dot_segments(path_str: str) -> str:
        if not path_str:
            return "/"
        inp = path_str
        output = []
        while inp:
            if inp.startswith("../"):
                inp = inp[3:]
            elif inp.startswith("./"):
                inp = inp[2:]
            elif inp.startswith("/./"):
                inp = "/" + inp[3:]
            elif inp == "/.":
                inp = "/"
            elif inp.startswith("/../"):
                inp = "/" + inp[4:]
                if output:
                    output.pop()
            elif inp == "/..":
                inp = "/"
                if output:
                    output.pop()
            elif inp in (".", ".."):
                inp = ""
            else:
                if inp.startswith("/"):
                    next_slash = inp.find("/", 1)
                    if next_slash == -1:
                        next_slash = len(inp)
                else:
                    next_slash = inp.find("/")
                    if next_slash == -1:
                        next_slash = len(inp)
                output.append(inp[:next_slash])
                inp = inp[next_slash:]
        return "".join(output)

    path = remove_dot_segments(path)

    # 5. Empty query/fragment
    query_part = f"?{query}" if query else ""
    fragment_part = f"#{fragment}" if fragment else ""

    # Authority parts
    auth_part = ""
    if userinfo:
        auth_part += f"{userinfo}@"
    auth_part += host
    if port:
        auth_part += f":{port}"

    return f"{scheme}://{auth_part}{path}{query_part}{fragment_part}"

import re
from typing import List, Optional, Dict

def parse_table(text: str) -> dict:
    lines = text.split('\n')
    lines = [line.rstrip('\r') for line in lines]

    first = 0
    while first < len(lines) and lines[first].strip(' \t') == '':
        first += 1
    last = len(lines) - 1
    while last >= 0 and lines[last].strip(' \t') == '':
        last -= 1

    if first > last:
        raise ValueError("No table lines found.")

    for i in range(first, last + 1):
        if lines[i].strip(' \t') == '':
            raise ValueError("Blank line between table lines.")

    table_lines = lines[first:last+1]

    if len(table_lines) < 2:
        raise ValueError("Fewer than two table lines.")

    def parse_cells(line: str) -> List[str]:
        line = line.strip(' \t')
        if line.startswith('|'):
            line = line[1:]

        last_idx = -1
        i = 0
        while i < len(line):
            if line[i] == '\\' and i + 1 < len(line) and line[i+1] == '|':
                i += 2
            elif line[i] == '|':
                last_idx = i
                i += 1
            else:
                i += 1

        if last_idx == len(line) - 1:
            line = line[:last_idx]

        cells = []
        current = []
        i = 0
        while i < len(line):
            if line[i] == '\\' and i + 1 < len(line) and line[i+1] == '|':
                current.append('|')
                i += 2
            elif line[i] == '|':
                cells.append(''.join(current))
                current = []
                i += 1
            else:
                current.append(line[i])
                i += 1
        cells.append(''.join(current))

        return [c.strip(' \t') for c in cells]

    header_cells = parse_cells(table_lines[0])
    delim_cells = parse_cells(table_lines[1])

    if len(delim_cells) != len(header_cells):
        raise ValueError("Delimiter row cell count mismatch.")

    align = []
    for cell in delim_cells:
        if not re.match(r'^:?-+:?$', cell):
            raise ValueError(f"Invalid delimiter cell: {cell}")
        if cell.startswith(':') and cell.endswith(':'):
            align.append('center')
        elif cell.startswith(':'):
            align.append('left')
        elif cell.endswith(':'):
            align.append('right')
        else:
            align.append(None)

    rows = []
    for line in table_lines[2:]:
        cells = parse_cells(line)
        if len(cells) < len(header_cells):
            cells.extend([''] * (len(header_cells) - len(cells)))
        elif len(cells) > len(header_cells):
            cells = cells[:len(header_cells)]
        rows.append(cells)

    return {
        "header": header_cells,
        "align": align,
        "rows": rows
    }

import re
from typing import List, Tuple, Optional

class Node:
    pass

class Int(Node):
    def __init__(self, val: int):
        self.val = val

class Symbol(Node):
    def __init__(self, name: str):
        self.name = name

class List(Node):
    def __init__(self, items: List[Node]):
        self.items = items

class Lambda(Node):
    def __init__(self, params: List[Symbol], body: Node):
        self.params = params
        self.body = body

class If(Node):
    def __init__(self, test: Node, then: Node, else_: Node):
        self.test = test
        self.then = then
        self.else_ = else_

class Let(Node):
    def __init__(self, bindings: List[Tuple[Symbol, Node]], body: Node):
        self.bindings = bindings
        self.body = body

class LetStar(Node):
    def __init__(self, bindings: List[Tuple[Symbol, Node]], body: Node):
        self.bindings = bindings
        self.body = body

RESERVED = {'let', 'let*', 'lambda', 'if'}
INTEGER_RE = re.compile(r'^-?\d+$')

def tokenize(src: str) -> List[str]:
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        c = src[i]
        if c.isspace():
            i += 1
        elif c == '(':
            tokens.append('(')
            i += 1
        elif c == ')':
            tokens.append(')')
            i += 1
        else:
            start = i
            while i < n and src[i] not in ' \t\n\r()':
                i += 1
            tokens.append(src[start:i])
    return tokens

def parse(tokens: List[str]) -> Node:
    idx = 0
    n = len(tokens)

    def parse_expr() -> Node:
        nonlocal idx
        if idx >= n:
            raise ValueError("Unexpected end of input")

        token = tokens[idx]

        if token == '(':
            idx += 1
            items = []
            while idx < n and tokens[idx] != ')':
                items.append(parse_expr())
            if idx >= n:
                raise ValueError("Unbalanced parentheses")
            if tokens[idx] == ')':
                idx += 1
            else:
                raise ValueError("Unbalanced parentheses")

            if not items:
                raise ValueError("Empty list ()")

            head = items[0]
            if isinstance(head, Symbol) and head.name in RESERVED:
                return validate_special_form(head.name, items)
            else:
                return List(items)

        elif token == ')':
            raise ValueError("Unexpected ')'")

        else:
            idx += 1
            if token in RESERVED:
                raise ValueError(f"Reserved symbol '{token}' used as operand/name")

            if INTEGER_RE.match(token):
                return Int(int(token))

            return Symbol(token)

    node = parse_expr()
    if idx < n:
        raise ValueError("Trailing tokens")
    return node

def validate_special_form(name: str, items: List[Node]) -> Node:
    if name == 'if':
        if len(items) != 4:
            raise ValueError(f"if requires 3 arguments, got {len(items)-1}")
        return If(items[1], items[2], items[3])

    if name == 'let':
        if len(items) < 3:
            raise ValueError("let requires at least a binding list and a body")
        if len(items) > 3:
            raise ValueError("let body must be a single expression")

        bindings_node = items[1]
        if not isinstance(bindings_node, List):
            raise ValueError("let bindings must be a list")

        bindings = []
        seen_names = set()
        for pair in bindings_node.items:
            if not isinstance(pair, List) or len(pair.items) != 2:
                raise ValueError("Each binding must be a list of two elements")
            name_node, expr_node = pair.items
            if not isinstance(name_node, Symbol):
                raise ValueError("Binding name must be a symbol")
            if name_node.name in RESERVED:
                raise ValueError(f"Reserved symbol '{name_node.name}' used as name")
            if name_node.name in seen_names:
                raise ValueError(f"Duplicate name '{name_node.name}' in let")
            seen_names.add(name_node.name)
            bindings.append((name_node, expr_node))

        return Let(bindings, items[2])

    if name == 'let*':
        if len(items) < 3:
            raise ValueError("let* requires at least a binding list and a body")
        if len(items) > 3:
            raise ValueError("let* body must be a single expression")

        bindings_node = items[1]
        if not isinstance(bindings_node, List):
            raise ValueError("let* bindings must be a list")

        bindings = []
        seen_names = set()
        for pair in bindings_node.items:
            if not isinstance(pair, List) or len(pair.items) != 2:
                raise ValueError("Each binding must be a list of two elements")
            name_node, expr_node = pair.items
            if not isinstance(name_node, Symbol):
                raise ValueError("Binding name must be a symbol")
            if name_node.name in RESERVED:
                raise ValueError(f"Reserved symbol '{name_node.name}' used as name")
            # let* allows repeating names, but we still track them for scope?
            # Actually, let* binds sequentially, so shadowing is allowed.
            # But we don't need to check for duplicates in the list itself like let.
            bindings.append((name_node, expr_node))

        return LetStar(bindings, items[2])

    if name == 'lambda':
        if len(items) < 3:
            raise ValueError("lambda requires parameters and a body")
        if len(items) > 3:
            raise ValueError("lambda body must be a single expression")

        params_node = items[1]
        if not isinstance(params_node, List):
            raise ValueError("lambda parameters must be a list")

        params = []
        seen_names = set()
        for param in params_node.items:
            if not isinstance(param, Symbol):
                raise ValueError("Lambda parameter must be a symbol")
            if param.name in RESERVED:
                raise ValueError(f"Reserved symbol '{param.name}' used as parameter")
            if param.name in seen_names:
                raise ValueError(f"Duplicate parameter '{param.name}' in lambda")
            seen_names.add(param.name)
            params.append(param)

        return Lambda(params, items[2])

    raise ValueError(f"Unknown reserved symbol '{name}'")

class Env(dict):
    def __init__(self, parent=None, **kwargs):
        super().__init__(**kwargs)
        self.parent = parent

    def __getitem__(self, key):
        if key in self:
            return super().__getitem__(key)
        if self.parent:
            return self.parent[key]
        raise ValueError(f"Unbound symbol '{key}'")

    def __setitem__(self, key, value):
        super().__setitem__(key, value)

class Function:
    def __init__(self, params: List[Symbol], body: Node, env: Env):
        self.params = params
        self.body = body
        self.env = env

def eval_node(node: Node, env: Env) -> object:
    if isinstance(node, Int):
        return node.val

    if isinstance(node, Symbol):
        return env[node.name]

    if isinstance(node, List):
        # Function call
        if not node.items:
            raise ValueError("Empty list cannot be called")

        f_node = node.items[0]
        args_nodes = node.items[1:]

        # Evaluate function
        f = eval_node(f_node, env)

        # Evaluate arguments
        args = [eval_node(arg, env) for arg in args_nodes]

        # Apply
        if isinstance(f, Function):
            if len(args) != len(f.params):
                raise ValueError(f"Function expects {len(f.params)} args, got {len(args)}")

            new_env = Env(parent=f.env)
            for param, arg in zip(f.params, args):
                new_env[param.name] = arg

            return eval_node(f.body, new_env)

        elif isinstance(f, str):
            # Built-in function
            return eval_builtin(f, args)

        else:
            raise ValueError(f"Value {type(f)} is not callable")

    if isinstance(node, Lambda):
        return Function(node.params, node.body, env)

    if isinstance(node, If):
        test_val = eval_node(node.test, env)
        if not isinstance(test_val, int):
            raise ValueError("if test must be integer")
        if test_val != 0:
            return eval_node(node.then, env)
        else:
            return eval_node(node.else_, env)

    if isinstance(node, Let):
        new_env = Env(parent=env)
        for name_node, expr_node in node.bindings:
            val = eval_node(expr_node, env) # Eval in outer scope
            new_env[name_node.name] = val
        return eval_node(node.body, new_env)

    if isinstance(node, LetStar):
        new_env = env
        for name_node, expr_node in node.bindings:
            val = eval_node(expr_node, new_env) # Eval in current scope (includes previous bindings)
            new_env = Env(parent=new_env, **{name_node.name: val})
        return eval_node(node.body, new_env)

    raise ValueError(f"Unknown node type {type(node)}")

def eval_builtin(name: str, args: List[object]) -> int:
    if name == '+':
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return sum(args) if args else 0

    if name == '*':
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        res = 1
        for a in args:
            res *= a
        return res

    if name == '-':
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if len(args) == 0:
            raise ValueError("- requires at least one argument")
        if len(args) == 1:
            return -args[0]
        res = args[0]
        for a in args[1:]:
            res -= a
        return res

    if name == '//':
        if len(args) != 2:
            raise ValueError("// requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if args[1] == 0:
            raise ZeroDivisionError("Division by zero")
        return args[0] // args[1]

    if name == '%':
        if len(args) != 2:
            raise ValueError("% requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if args[1] == 0:
            raise ZeroDivisionError("Division by zero")
        return args[0] % args[1]

    if name == '<':
        if len(args) != 2:
            raise ValueError("< requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return 1 if args[0] < args[1] else 0

    if name == '=':
        if len(args) != 2:
            raise ValueError("=" requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return 1 if args[0] == args[1] else 0

    if name == '>':
        if len(args) != 2:
            raise ValueError("> requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return 1 if args[0] > args[1] else 0

    if name == 'min':
        if len(args) < 1:
            raise ValueError("min requires at least one argument")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return min(args)

    if name == 'max':
        if len(args) < 1:
            raise ValueError("max requires at least one argument")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return max(args)

    raise ValueError(f"Unknown built-in '{name}'")

def lisp_eval(src: str) -> int:
    tokens = tokenize(src)
    if not tokens:
        raise ValueError("Empty input")

    node = parse(tokens)
    initial_env = Env()
    # Bind built-ins
    initial_env['+'] = '+'
    initial_env['*'] = '*'
    initial_env['-'] = '-'
    initial_env['//'] = '//'
    initial_env['%'] = '%'
    initial_env['<'] = '<'
    initial_env['='] = '='
    initial_env['>'] = '>'
    initial_env['min'] = 'min'
    initial_env['max'] = 'max'

    result = eval_node(node, initial_env)

    if isinstance(result, Function):
        raise ValueError("Result is a function")
    if not isinstance(result, int):
        raise ValueError(f"Result is not an integer: {type(result)}")

    return result

