import re
from typing import Any, Dict, List, Tuple, Callable

# Reserved symbols
RESERVED = {'let', 'let*', 'lambda', 'if'}

class Closure:
    def __init__(self, params: List[str], body: Any, env: Dict[str, Any]):
        self.params = params
        self.body = body
        self.env = env

def tokenize(src: str) -> List[Any]:
    """Tokenizes the source string into a list of integers, strings, and parentheses."""
    tokens = []
    # Regex matches: whitespace (ignored), parentheses, or atoms
    # We use finditer to process matches sequentially
    pattern = re.compile(r'\s+|\(|\)|[^\s\(\)]+')

    for match in pattern.finditer(src):
        t = match.group()
        if t == '(':
            tokens.append('(')
        elif t == ')':
            tokens.append(')')
        else:
            # Atom: check if integer
            if re.match(r'^-?\d+$', t):
                tokens.append(int(t))
            else:
                tokens.append(t)
    return tokens

def parse(tokens: List[Any]) -> Any:
    """Parses a list of tokens into an AST (nested lists, ints, strings)."""
    if not tokens:
        raise ValueError("Empty input")

    # Use a pointer/index approach or iterator. 
    # Since we need to consume exactly one expression, we'll use a helper.

    def parse_expr():
        if not tokens:
            raise ValueError("Unexpected end of input")

        t = tokens.pop(0)

        if t == '(':
            lst = []
            while tokens:
                if tokens[0] == ')':
                    tokens.pop(0)
                    break
                lst.append(parse_expr())
            else:
                # Loop finished without finding ')'
                raise ValueError("Unbalanced parentheses")
            return lst
        elif t == ')':
            raise ValueError("Unbalanced parentheses")
        else:
            return t

    ast = parse_expr()

    if tokens:
        raise ValueError("Trailing tokens after first expression")

    return ast

def validate(node: Any, is_name: bool = False) -> None:
    """
    Validates the AST structure and reserved word usage.
    Raises ValueError on syntax errors.
    """
    # Check for empty list
    if isinstance(node, list):
        if not node:
            raise ValueError("Empty list '()' is not allowed")

        head = node[0]

        # Head must be a symbol (string) or integer (for calls)
        # But reserved words must be handled specifically.

        if isinstance(head, str):
            if head in RESERVED:
                # Validate specific reserved word structures
                if head == 'if':
                    if len(node) != 4:
                        raise ValueError("if must have 3 arguments: (if test then else)")
                    validate(node[1]) # test
                    validate(node[2]) # then
                    validate(node[3]) # else
                elif head == 'let':
                    if len(node) != 3:
                        raise ValueError("let must have 2 arguments: (let bindings body)")
                    bindings = node[1]
                    if not isinstance(bindings, list):
                        raise ValueError("let bindings must be a list")
                    names = set()
                    for binding in bindings:
                        if not isinstance(binding, list) or len(binding) != 2:
                            raise ValueError("Each let binding must be a list of two elements: (name expr)")
                        name = binding[0]
                        if not isinstance(name, str):
                            raise ValueError("let binding names must be symbols")
                        if name in RESERVED:
                            raise ValueError(f"Reserved symbol '{name}' cannot be used as a name")
                        if name in names:
                            raise ValueError(f"Duplicate name '{name}' in let")
                        names.add(name)
                        validate(binding[1]) # expr
                    validate(node[2]) # body
                elif head == 'let*':
                    if len(node) != 3:
                        raise ValueError("let* must have 2 arguments: (let* bindings body)")
                    bindings = node[1]
                    if not isinstance(bindings, list):
                        raise ValueError("let* bindings must be a list")
                    # Names can repeat in let*
                    for binding in bindings:
                        if not isinstance(binding, list) or len(binding) != 2:
                            raise ValueError("Each let* binding must be a list of two elements")
                        name = binding[0]
                        if not isinstance(name, str):
                            raise ValueError("let* binding names must be symbols")
                        if name in RESERVED:
                            raise ValueError(f"Reserved symbol '{name}' cannot be used as a name")
                        validate(binding[1])
                    validate(node[2])
                elif head == 'lambda':
                    if len(node) != 3:
                        raise ValueError("lambda must have 2 arguments: (lambda params body)")
                    params = node[1]
                    if not isinstance(params, list):
                        raise ValueError("lambda params must be a list")
                    names = set()
                    for param in params:
                        if not isinstance(param, str):
                            raise ValueError("lambda params must be symbols")
                        if param in RESERVED:
                            raise ValueError(f"Reserved symbol '{param}' cannot be used as a name")
                        if param in names:
                            raise ValueError(f"Duplicate name '{param}' in lambda")
                        names.add(param)
                    validate(node[2])
            else:
                # Head is a regular function symbol
                # Validate arguments
                for arg in node[1:]:
                    validate(arg)
        elif isinstance(head, int):
            # Head is an integer, syntactically valid (runtime error if called)
            for arg in node[1:]:
                validate(arg)
        else:
            # Head is not string or int? Should not happen with our tokenizer
            raise ValueError("Invalid expression head")

    elif isinstance(node, str):
        # Atom is a symbol
        if is_name:
            # If it's a name, it must be a symbol (checked by caller usually)
            # But here we just check if it's reserved
            if node in RESERVED:
                raise ValueError(f"Reserved symbol '{node}' used as a name or operand")
        else:
            # If it's an operand or standalone
