            # but strict type checking is runtime.
            # Prompt: "A function passed where a built-in needs an integer raises ValueError"
            # This applies to built-ins. For user functions, we assume they handle it or fail later.

            # Create new scope
            new_env = dict(head_val.env)
            for param, arg_val in zip(head_val.params, arg_vals):
                new_env[param] = arg_val
            return evaluate(head_val.body, new_env)

        elif isinstance(head_val, str):
            # Built-in function
            if head_val not in BUILTINS:
                raise ValueError(f"Unbound function '{head_val}'")
            return BUILTINS[head_val](arg_vals)

        elif isinstance(head_val, int):
            raise ValueError("Cannot call an integer")

        else:
            raise ValueError("Cannot call non-function")

    raise ValueError("Invalid expression")

