import re
from typing import Any, Dict, List, Tuple, Callable

# Reserved symbols
RESERVED = {'let', 'let*', 'lambda', 'if'}

class Closure:
    def __init__(self, params: List[str], body: Any, env: Dict[str, Any]):
        self.params = params
        self.body = body
        self.env = env

def tokenize(src: str) -> List[Any]:
    """Tokenizes the source string into a list of integers, strings, and parentheses."""
    tokens = []
    # Regex matches: whitespace, parentheses, or atoms
    pattern = re.compile(r'\s+|\(|\)|[^\s\(\)]+')

    for match in pattern.finditer(src):
        t = match.group()
        if t.isspace():
            continue
        if t == '(':
            tokens.append('(')
        elif t == ')':
            tokens.append(')')
        else:
            # Atom: check if integer
            if re.match(r'^-?\d+$', t):
                tokens.append(int(t))
            else:
                tokens.append(t)
    return tokens

def parse(tokens: List[Any]) -> Any:
    """Parses a list of tokens into an AST (nested lists, ints, strings)."""
    if not tokens:
        raise ValueError("Empty input")

    def parse_expr():
        if not tokens:
            raise ValueError("Unexpected end of input")

        t = tokens.pop(0)

        if t == '(':
            lst = []
            while tokens:
                if tokens[0] == ')':
                    tokens.pop(0)
                    break
                lst.append(parse_expr())
            else:
                raise ValueError("Unbalanced parentheses")
            return lst
        elif t == ')':
            raise ValueError("Unbalanced parentheses")
        else:
            return t

    ast = parse_expr()

    if tokens:
        raise ValueError("Trailing tokens after first expression")

    return ast

def validate(node: Any) -> None:
    """
    Validates the AST structure and reserved word usage.
    Raises ValueError on syntax errors.
    """
    if isinstance(node, list):
        if not node:
            raise ValueError("Empty list '()' is not allowed")

        head = node[0]

        # Validate the head expression itself first, unless it's a reserved symbol
        if not isinstance(head, str) or head not in RESERVED:
            validate(head)

        if isinstance(head, str):
            if head in RESERVED:
                if head == 'if':
                    if len(node) != 4:
                        raise ValueError("if must have 3 arguments")
                    validate(node[1])
                    validate(node[2])
                    validate(node[3])
                elif head == 'let':
                    if len(node) != 3:
                        raise ValueError("let must have 2 arguments")
                    bindings = node[1]
                    if not isinstance(bindings, list):
                        raise ValueError("let bindings must be a list")
                    names = set()
                    for binding in bindings:
                        if not isinstance(binding, list) or len(binding) != 2:
                            raise ValueError("Each let binding must be a list of two elements")
                        name = binding[0]
                        if not isinstance(name, str):
                            raise ValueError("let binding names must be symbols")
                        if name in RESERVED:
                            raise ValueError(f"Reserved symbol '{name}' cannot be used as a name")
                        if name in names:
                            raise ValueError(f"Duplicate name '{name}' in let")
                        names.add(name)
                        validate(binding[1])
                    validate(node[2])
                elif head == 'let*':
                    if len(node) != 3:
                        raise ValueError("let* must have 2 arguments")
                    bindings = node[1]
                    if not isinstance(bindings, list):
                        raise ValueError("let* bindings must be a list")
                    for binding in bindings:
                        if not isinstance(binding, list) or len(binding) != 2:
                            raise ValueError("Each let* binding must be a list of two elements")
                        name = binding[0]
                        if not isinstance(name, str):
                            raise ValueError("let* binding names must be symbols")
                        if name in RESERVED:
                            raise ValueError(f"Reserved symbol '{name}' cannot be used as a name")
                        validate(binding[1])
                    validate(node[2])
                elif head == 'lambda':
                    if len(node) != 3:
                        raise ValueError("lambda must have 2 arguments")
                    params = node[1]
                    if not isinstance(params, list):
                        raise ValueError("lambda params must be a list")
                    names = set()
                    for param in params:
                        if not isinstance(param, str):
                            raise ValueError("lambda params must be symbols")
                        if param in RESERVED:
                            raise ValueError(f"Reserved symbol '{param}' cannot be used as a name")
                        if param in names:
                            raise ValueError(f"Duplicate name '{param}' in lambda")
                        names.add(param)
                    validate(node[2])
            else:
                # Regular function call
                for arg in node[1:]:
                    validate(arg)
        elif isinstance(head, int):
            # Head is an integer, syntactically valid (runtime error if called)
            for arg in node[1:]:
                validate(arg)
        elif isinstance(head, list):
            # Head is a list (e.g. higher-order function call)
            # Already validated head above. Now validate args.
            for arg in node[1:]:
                validate(arg)
        else:
            raise ValueError("Invalid expression head")

    elif isinstance(node, str):
        if node in RESERVED:
            raise ValueError(f"Reserved symbol '{node}' used")

    elif isinstance(node, int):
        pass
    else:
        raise ValueError("Invalid token type")

def evaluate(node: Any, env: Dict[str, Any]) -> Any:
    """
    Evaluates the AST node in the given environment.
    Returns a value (int, Closure, or builtin function).
    """
    if isinstance(node, int):
        return node

    if isinstance(node, str):
        if node in RESERVED:
            raise ValueError(f"Reserved symbol '{node}' evaluated")
        if node not in env:
            raise ValueError(f"Unbound symbol '{node}'")
        return env[node]

    if isinstance(node, list):
        head = node[0]

        if isinstance(head, str):
            if head == 'if':
                if len(node) != 4:
                    raise ValueError("if needs 3 args")
                test = evaluate(node[1], env)
                if not isinstance(test, int):
                    raise ValueError("if test must be int")
                if test != 0:
                    return evaluate(node[2], env)
                else:
                    return evaluate(node[3], env)

            elif head == 'let':
                if len(node) != 3:
                    raise ValueError("let needs 2 args")
                bindings = node[1]
                body = node[2]
                new_env = dict(env)
                for binding in bindings:
                    name = binding[0]
                    expr = binding[1]
                    val = evaluate(expr, env) # Evaluate in outer env
                    new_env[name] = val
                return evaluate(body, new_env)

            elif head == 'let*':
                if len(node) != 3:
                    raise ValueError("let* needs 2 args")
                bindings = node[1]
                body = node[2]
                new_env = dict(env)
                for binding in bindings:
                    name = binding[0]
                    expr = binding[1]
                    val = evaluate(expr, new_env) # Evaluate in current env
                    new_env[name] = val
                return evaluate(body, new_env)

            elif head == 'lambda':
                if len(node) != 3:
                    raise ValueError("lambda needs 2 args")
                params = node[1]
                body = node[2]
                return Closure(params, body, env)

            else:
                # Regular function call
                head_val = evaluate(head, env)
                arg_vals = [evaluate(arg, env) for arg in node[1:]]
                return apply_function(head_val, arg_vals)

        elif isinstance(head, int):
            raise ValueError("Cannot call integer")
        elif isinstance(head, list):
            # Head is a list (e.g. lambda expression)
            head_val = evaluate(head, env)
            arg_vals = [evaluate(arg, env) for arg in node[1:]]
            return apply_function(head_val, arg_vals)
        else:
            raise ValueError("Invalid head")

    raise ValueError("Invalid expression")

def apply_function(func: Any, args: List[Any]) -> Any:
    if isinstance(func, Closure):
        if len(args) != len(func.params):
            raise ValueError("Argument count mismatch")
        new_env = dict(func.env)
        for p, a in zip(func.params, args):
            new_env[p] = a
        return evaluate(func.body, new_env)

    elif callable(func): # Builtin
        # Check if args are ints for builtins
        for arg in args:
            if not isinstance(arg, int):
                raise ValueError("Built-in expects integer argument")
        return func(args)
    else:
        raise ValueError("Not a function")

# Built-in functions
def builtin_add(args: List[int]) -> int:
    if not args:
        return 0
    return sum(args)

def builtin_mul(args: List[int]) -> int:
    if not args:
        return 1
    res = 1
    for x in args:
        res *= x
    return res

def builtin_sub(args: List[int]) -> int:
    if len(args) == 0:
        raise ValueError("Subtraction requires at least one argument")
    if len(args) == 1:
        return -args[0]
    res = args[0]
    for x in args[1:]:
        res -= x
    return res

def builtin_div(args: List[int]) -> int:
    if len(args) != 2:
        raise ValueError("Division requires exactly 2 arguments")
    if args[1] == 0:
        raise ZeroDivisionError("Division by zero")
    return args[0] // args[1]

def builtin_mod(args: List[int]) -> int:
    if len(args) != 2:
        raise ValueError("Modulo requires exactly 2 arguments")
    if args[1] == 0:
        raise ZeroDivisionError("Modulo by zero")
    return args[0] % args[1]

def builtin_lt(args: List[int]) -> int:
    if len(args) != 2:
        raise ValueError("Comparison requires exactly 2 arguments")
    return 1 if args[0] < args[1] else 0

def builtin_eq(args: List[int]) -> int:
    if len(args) != 2:
        raise ValueError("Comparison requires exactly 2 arguments")
    return 1 if args[0] == args[1] else 0

def builtin_gt(args: List[int]) -> int:
    if len(args) != 2:
        raise ValueError("Comparison requires exactly 2 arguments")
    return 1 if args[0] > args[1] else 0

def builtin_min(args: List[int]) -> int:
    if not args:
        raise ValueError("min requires at least 1 argument")
    return min(args)

def builtin_max(args: List[int]) -> int:
    if not args:
        raise ValueError("max requires at least 1 argument")
    return max(args)

BUILTINS = {
    '+': builtin_add,
    '*': builtin_mul,
    '-': builtin_sub,
    '//': builtin_div,
    '%': builtin_mod,
    '<': builtin_lt,
    '=': builtin_eq,
    '>': builtin_gt,
    'min': builtin_min,
    'max': builtin_max,
}

