                    elements.append(parse_atom(tokens[idx]))
                    idx += 1
            if idx >= len(tokens):
                raise ValueError("Unbalanced parentheses")
            if tokens[idx] == ')':
                idx += 1
            return elements, idx
        elif token == ')':
            raise ValueError("Unexpected ')'")
        else:
