        '+': b_plus,
        '*': b_mul,
        '-': b_sub,
        '//': b_div,
        '%': b_mod,
        '<': b_lt,
        '=': b_eq,
        '>': b_gt,
        'min': b_min,
        'max': b_max,
    }

