    # Global env contains builtins
    global_env = dict(builtins)

    def eval_expr(node, env):
        if isinstance(node, int):
            return node
        if isinstance(node, str):
            # Symbol lookup
            if node in env:
                return env[node]
            else:
                raise ValueError(f"Unbound symbol '{node}'")

