                raise ValueError(f"{head} requires exactly 2 arguments: bindings and body")
            bindings = args[0]
            if not isinstance(bindings, list):
                raise ValueError(f"{head} bindings must be a list")

            names_seen = set()
            for binding in bindings:
                if not isinstance(binding, list) or len(binding) != 2:
                    raise ValueError(f"{head} binding must be a list of 2 elements")

                name = binding[0]
                if not isinstance(name, str):
                    raise ValueError(f"{head} binding name must be a symbol")
                if name in reserved_symbols:
                    raise ValueError(f"Reserved symbol '{name}' used as binding name")

                if head == 'let' and name in names_seen:
                    raise ValueError(f"Duplicate binding name '{name}' in let")
                names_seen.add(name)

        else:
            # Should not happen due to check above
            pass

    try:
        validate(tree)
    except ValueError as e:
        raise e

    # --- Evaluation ---

    # Built-in functions
    def b_plus(args):
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        return sum(args) if args else 0

    def b_mul(args):
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if not args: return 1
        return reduce(lambda x, y: x * y, args)

    def b_sub(args):
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if len(args) == 0:
            raise ValueError("Zero arguments not allowed for -")
        if len(args) == 1:
            return -args[0]
        res = args[0]
        for a in args[1:]:
            res -= a
        return res

    def b_div(args):
        if len(args) != 2:
            raise ValueError("// requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if args[1] == 0:
            raise ZeroDivisionError("Division by zero")
        return args[0] // args[1]

    def b_mod(args):
        if len(args) != 2:
            raise ValueError("% requires exactly 2 arguments")
        if not all(isinstance(a, int) for a in args):
            raise ValueError("Arguments must be integers")
        if args[1] == 0:
            raise ZeroDivisionError("Division by zero")
        return args[0] % args[1]

    def b_lt(args):
        if len(args) != 2: raise ValueError("< requires 2 args")
        if not all(isinstance(a, int) for a in args): raise ValueError("Args must be int")
        return 1 if args[0] < args[1] else 0

    def b_eq(args):
        if len(args) != 2: raise ValueError("= requires 2 args")
        if not all(isinstance(a, int) for a in args): raise ValueError("Args must be int")
        return 1 if args[0] == args[1] else 0

    def b_gt(args):
        if len(args) != 2: raise ValueError("> requires 2 args")
        if not all(isinstance(a, int) for a in args): raise ValueError("Args must be int")
        return 1 if args[0] > args[1] else 0

    def b_min(args):
        if not args: raise ValueError("min requires at least 1 arg")
        if not all(isinstance(a, int) for a in args): raise ValueError("Args must be int")
        return min(args)

    def b_max(args):
        if not args: raise ValueError("max requires at least 1 arg")
        if not all(isinstance(a, int) for a in args): raise ValueError("Args must be int")
        return max(args)

    builtins = {
        '+': b_plus,
        '*': b_mul,
        '-': b_sub,
        '//': b_div,
        '%': b_mod,
        '<': b_lt,
        '=': b_eq,
        '>': b_gt,
        'min': b_min,
        'max': b_max,
    }

    # Environment
    # Global env contains builtins
    global_env = dict(builtins)

    def eval_expr(node, env):
        if isinstance(node, int):
            return node
        if isinstance(node, str):
            # Symbol lookup
            if node in env:
                return env[node]
            else:
                raise ValueError(f"Unbound symbol '{node}'")

        if isinstance(node, list):
            # Check if special form
            head = node[0]

            if isinstance(head, str) and head in reserved_symbols:
                return eval_special(head, node[1:], env)
            else:
                # Function call
                func_val = eval_expr(head, env)
                if not callable(func_val):
                    raise ValueError(f"Expected function, got {type(func_val)}")

                # Evaluate arguments left to right
                args = [eval_expr(arg, env) for arg in node[1:]]

                # Call function
                try:
                    res = func_val(args)
                except TypeError:
                    # Arity mismatch or type error inside function
                    raise ValueError("Function call error")

                if not isinstance(res, int):
                    raise ValueError("Function must return an integer")
                return res

    def eval_special(head, args, env):
        if head == 'if':
            if len(args) != 3:
                raise ValueError("if requires 3 args")
            test = eval_expr(args[0], env)
            if not isinstance(test, int):
                raise ValueError("if test must be integer")
            if test != 0:
                return eval_expr(args[1], env)
            else:
                return eval_expr(args[2], env)

        elif head == 'lambda':
            if len(args) != 2:
                raise ValueError("lambda requires 2 args")
            params = args[0]
            body = args[1]

            def closure(func_args):
                if len(func_args) != len(params):
                    raise ValueError("Argument count mismatch")
                # Create new env extending closure env
                new_env = dict(env)
                for p, v in zip(params, func_args):
                    new_env[p] = v
                return eval_expr(body, new_env)

            return closure

        elif head == 'let':
            if len(args) != 2:
                raise ValueError("let requires 2 args")
            bindings = args[0]
            body = args[1]

            # Evaluate bindings in current env (outer scope)
            new_env = dict(env)
            for binding in bindings:
                name = binding[0]
                expr = binding[1]
                val = eval_expr(expr, env)
                new_env[name] = val

            return eval_expr(body, new_env)

        elif head == 'let*':
            if len(args) != 2:
                raise ValueError("let* requires 2 args")
            bindings = args[0]
            body = args[1]

            new_env = dict(env)
            for binding in bindings:
                name = binding[0]
                expr = binding[1]
                val = eval_expr(expr, new_env) # Bindings see earlier bindings
                new_env[name] = val

            return eval_expr(body, new_env)

        else:
            raise ValueError(f"Unknown special form '{head}'")

    # Final check: result must be int
    result = eval_expr(tree, global_env)
    if not isinstance(result, int):
        raise ValueError("Result must be an integer")

    return result

import re

def lisp_eval(src: str) -> int:
    """
    Evaluates a small Lisp expression.
    """

    # --- Tokenizer and Parser ---

    class LispParser:
        def __init__(self, src):
            self.src = src
            self.pos = 0

        def skip_ws(self):
            while self.pos < len(self.src) and self.src[self.pos].isspace():
                self.pos += 1

        def peek(self):
            self.skip_ws()
            if self.pos < len(self.src):
                return self.src[self.pos]
            return None

        def parse_expr(self):
            self.skip_ws()
            if self.pos >= len(self.src):
                raise ValueError("Unexpected end of input")

            char = self.src[self.pos]

            if char == '(':
                return self.parse_list()
            elif char == ')':
                raise ValueError("Unbalanced parentheses")
            else:
                atom_str = self.read_atom()
                if not atom_str:
                    raise ValueError("Empty atom")

                # Check if integer
                # "optional '-' followed by one or more ASCII digits"
                # We use a regex to be precise about the format
                if re.fullmatch(r'-?\d+', atom_str):
                    return int(atom_str)
                else:
                    return atom_str # It's a symbol

        def read_atom(self):
            start = self.pos
            # Atoms are maximal runs of characters that are not whitespace or parentheses
            while self.pos < len(self.src) and self.src[self.pos] not in ' \t\n\r()':
                self.pos += 1
            return self.src[start:self.pos]

        def parse_list(self):
            self.skip_ws()
            if self.pos >= len(self.src) or self.src[self.pos] != '(':
                raise ValueError("Expected '('")
            self.pos += 1 # consume '('

            items = []
            while True:
                self.skip_ws()
                if self.pos >= len(self.src):
                    raise ValueError("Unbalanced parentheses")

                if self.src[self.pos] == ')':
                    self.pos += 1 # consume ')'
                    return items

                items.append(self.parse_expr())

    # --- Syntax Validation ---

    RESERVED_WORDS = {'let', 'let*', 'lambda', 'if'}

    def validate(ast):
        """
        Validates the AST structure.
        Raises ValueError on syntax errors.
        """
        if isinstance(ast, list):
            if not ast:
                raise ValueError("Empty list is not allowed")

            head = ast[0]

            # Check if head is a reserved word
            if isinstance(head, str) and head in RESERVED_WORDS:
                # Reserved words must be used as special forms
                if head == 'let':
                    # (let ((name expr) ...) body)
                    # List must have exactly 3 elements: head, bindings, body
                    if len(ast) != 3:
                        raise ValueError("Invalid let syntax")

                    bindings_list = ast[1]
                    body = ast[2]

                    if not isinstance(bindings_list, list):
                        raise ValueError("Bindings must be a list")

                    if not isinstance(body, (int, str, list)):
                        raise ValueError("Body must be an expression")

                    # Validate bindings
                    for binding in bindings_list:
                        if not isinstance(binding, list):
                            raise ValueError("Each binding must be a list")
                        if len(binding) != 2:
                            raise ValueError("Each binding must have exactly 2 elements")

                        name = binding[0]
                        expr = binding[1]

                        if not isinstance(name, str):
                            raise ValueError("Binding name must be a symbol")
                        if name in RESERVED_WORDS:
                            raise ValueError("Reserved symbol used as binding name")

                        validate(expr)

                    # Check distinct names for let
                    names = [b[0] for b in bindings_list]
                    if len(names) != len(set(names)):
                        raise ValueError("Binding names must be distinct in let")

                    validate(body)

                elif head == 'let*':
                    # (let* ((name expr) ...) body)
                    # Similar to let, but names can repeat
                    if len(ast) != 3:
                        raise ValueError("Invalid let* syntax")

                    bindings_list = ast[1]
                    body = ast[2]

                    if not isinstance(bindings_list, list):
                        raise ValueError("Bindings must be a list")

                    if not isinstance(body, (int, str, list)):
                        raise ValueError("Body must be an expression")

                    for binding in bindings_list:
                        if not isinstance(binding, list):
                            raise ValueError("Each binding must be a list")
                        if len(binding) != 2:
                            raise ValueError("Each binding must have exactly 2 elements")

                        name = binding[0]
                        expr = binding[1]

                        if not isinstance(name, str):
                            raise ValueError("Binding name must be a symbol")
                        if name in RESERVED_WORDS:
                            raise ValueError("Reserved symbol used as binding name")

                        validate(expr)

                    # Names can repeat in let*
                    validate(body)

                elif head == 'lambda':
                    # (lambda (name ...) body)
                    if len(ast) != 3:
                        raise ValueError("Invalid lambda syntax")

                    args_list = ast[1]
                    body = ast[2]

                    if not isinstance(args_list, list):
                        raise ValueError("Arguments must be a list")

                    if not isinstance(body, (int, str, list)):
                        raise ValueError("Body must be an expression")

                    names = []
                    for name in args_list:
                        if not isinstance(name, str):
                            raise ValueError("Lambda argument must be a symbol")
                        if name in RESERVED_WORDS:
                            raise ValueError("Reserved symbol used as lambda argument")
                        names.append(name)

                    if len(names) != len(set(names)):
                        raise ValueError("Lambda argument names must be distinct")

                    validate(body)

                elif head == 'if':
                    # (if test then else)
                    if len(ast) != 4:
                        raise ValueError("Invalid if syntax")

                    test = ast[1]
                    then_branch = ast[2]
                    else_branch = ast[3]

                    if not isinstance(test, (int, str, list)):
                        raise ValueError("Test must be an expression")
                    if not isinstance(then_branch, (int, str, list)):
                        raise ValueError("Then branch must be an expression")
                    if not isinstance(else_branch, (int, str, list)):
                        raise ValueError("Else branch must be an expression")

                    validate(test)
                    validate(then_branch)
                    validate(else_branch)

                else:
                    # Should not happen due to check above
                    raise ValueError(f"Unknown reserved word usage: {head}")

            else:
                # Head is not a reserved word (or is int)
                # It's a function call or just a list
                # Validate all elements
                for item in ast:
                    validate(item)

        elif isinstance(ast, str):
            # Symbol
            if ast in RESERVED_WORDS:
                raise ValueError(f"Reserved symbol '{ast}' used as operand/name")
            # Symbols are valid identifiers unless reserved
            # We assume valid symbol format (not integer) since parser handles int conversion
            pass

        elif isinstance(ast, int):
            # Integer is valid
            pass

        else:
            raise ValueError(f"Invalid AST node type")

    # --- Evaluation ---

    # Built-in functions
    def make_builtin(func):
        def wrapper(*args):
            return func(*args)
        wrapper.is_builtin = True
        return wrapper

    def builtin_add(*args):
        return sum(args)

    def builtin_mul(*args):
        res = 1
        for a in args:
            res *= a
        return res

    def builtin_sub(*args):
        if len(args) == 0:
            raise ValueError("Subtraction requires at least 1 argument")
        if len(args) == 1:
            return -args[0]
        res = args[0]
        for a in args[1:]:
            res -= a
        return res

    def builtin_div(*args):
        if len(args) != 2:
            raise ValueError("Division requires exactly 2 arguments")
        a, b = args
        if b == 0:
            raise ZeroDivisionError("Division by zero")
        # Floor semantics like Python
        return a // b

    def builtin_mod(*args):
        if len(args) != 2:
            raise ValueError("Modulo requires exactly 2 arguments")
        a, b = args
        if b == 0:
            raise ZeroDivisionError("Modulo by zero")
        return a % b

    def builtin_lt(*args):
        if len(args) != 2:
            raise ValueError("Comparison requires exactly 2 arguments")
        return 1 if args[0] < args[1] else 0

    def builtin_eq(*args):
        if len(args) != 2:
            raise ValueError("Comparison requires exactly 2 arguments")
        return 1 if args[0] == args[1] else 0

    def builtin_gt(*args):
        if len(args) != 2:
            raise ValueError("Comparison requires exactly 2 arguments")
        return 1 if args[0] > args[1] else 0

    def builtin_min(*args):
        if len(args) < 1:
            raise ValueError("Min requires at least 1 argument")
        return min(args)

    def builtin_max(*args):
        if len(args) < 1:
            raise ValueError("Max requires at least 1 argument")
        return max(args)

    # Global environment
    global_env = {
        '+': make_builtin(builtin_add),
        '*': make_builtin(builtin_mul),
        '-': make_builtin(builtin_sub),
        '//': make_builtin(builtin_div),
        '%': make_builtin(builtin_mod),
        '<': make_builtin(builtin_lt),
        '=': make_builtin(builtin_eq),
        '>': make_builtin(builtin_gt),
        'min': make_builtin(builtin_min),
        'max': make_builtin(builtin_max),
    }

    class Closure:
        def __init__(self, params, body, env):
            self.params = params
            self.body = body
            self.env = env

        def __call__(self, *args):
            # Create new environment
            if len(self.params) != len(args):
                raise ValueError(f"Arity mismatch: expected {len(self.params)}, got {len(args)}")

            new_env = dict(self.env)
            for param, arg in zip(self.params, args):
                new_env[param] = arg

            return eval_expr(self.body, new_env)

    def eval_expr(ast, env):
        if isinstance(ast, int):
            return ast

        if isinstance(ast, str):
            # Symbol lookup
            if ast in env:
                return env[ast]
            else:
                raise ValueError(f"Unbound symbol: {ast}")

        if isinstance(ast, list):
            if not ast:
                raise ValueError("Empty list")

            head = ast[0]
            args_ast = ast[1:]

            # Evaluate head
            f_val = eval_expr(head, env)

            # Evaluate arguments
            args_vals = [eval_expr(arg, env) for arg in args_ast]

            # Check if callable
            if callable(f_val):
                # Check if it's a builtin (expects ints) or closure
                # Builtin check
                if hasattr(f_val, 'is_builtin'):
                    # Builtin expects integers. Check types.
                    for arg in args_vals:
                        if not isinstance(arg, int):
                            raise ValueError(f"Builtin expects integer argument, got {type(arg)}")
                    return f_val(*args_vals)
                else:
                    # Closure
                    return f_val(*args_vals)
            else:
                raise ValueError("Attempt to call non-function")

        raise ValueError(f"Invalid expression type")

    # --- Main Execution ---

    try:
        parser = LispParser(src)
        ast = parser.parse()
        validate(ast)
        result = eval_expr(ast, global_env)

        if not isinstance(result, int):
            raise ValueError("Result must be an integer")

        return result

    except ValueError:
        raise
    except Exception as e:
        # Wrap other errors as ValueError if needed, but prompt implies specific errors
        raise ValueError(str(e))

import re

def lisp_eval(src: str) -> int:
    """
    Evaluates a small Lisp expression.
    """
    if not src or not src.strip():
        raise ValueError("Empty input")

    # Tokenizer
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        if src[i].isspace():
            i += 1
        elif src[i] in '()':
            tokens.append(src[i])
            i += 1
        else:
            j = i
            while j < n and src[j] not in ' \t\n\r()':
                j += 1
            tokens.append(src[i:j])
            i = j

    # Parser
    pos = 0
    def parse_expr():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of input")
        tok = tokens[pos]
        if tok == '(':
            pos += 1
            lst = []
            while True:
                if pos >= len(tokens):
                    raise ValueError("Unbalanced parentheses")
                if tokens[pos] == ')':
                    pos += 1
                    return lst
                lst.append(parse_expr())
        elif tok == ')':
            raise ValueError("Unbalanced parentheses")
        else:
            pos += 1
            if re.fullmatch(r'-?\d+', tok):
                return int(tok)
            return tok

    ast = parse_expr()
    if pos < len(tokens):
        raise ValueError("Trailing tokens after expression")

