    RESERVED = {'let', 'let*', 'lambda', 'if'}

    def validate(ast):
        if isinstance(ast, list):
            if not ast:
                raise ValueError("Empty list")
            head = ast[0]
            if isinstance(head, str) and head in RESERVED:
                if head == 'let':
                    if len(ast) != 3: raise ValueError("let syntax")
                    bindings, body = ast[1], ast[2]
                    if not isinstance(bindings, list): raise ValueError("let bindings")
                    for b in bindings:
                        if not isinstance(b, list) or len(b) != 2: raise ValueError("let binding")
                        name, expr = b
                        if not isinstance(name, str) or name in RESERVED or re.fullmatch(r'-?\d+', name): raise ValueError("let name")
                        validate(expr)
                    names = [b[0] for b in bindings]
                    if len(names) != len(set(names)): raise ValueError("let distinct names")
                    validate(body)
                elif head == 'let*':
                    if len(ast) != 3: raise ValueError("let* syntax")
                    bindings, body = ast[1], ast[2]
                    if not isinstance(bindings, list): raise ValueError("let* bindings")
                    for b in bindings:
                        if not isinstance(b, list) or len(b) != 2: raise ValueError("let* binding")
                        name, expr = b
                        if not isinstance(name, str) or name in RESERVED or re.fullmatch(r'-?\d+', name): raise ValueError("let* name")
                        validate(expr)
                    # let* allows repeated names
                    validate(body)
                elif head == 'lambda':
                    if len(ast) != 3: raise ValueError("lambda syntax")
                    params, body = ast[1], ast[2]
                    if not isinstance(params, list): raise ValueError("lambda params")
                    names = []
                    for p in params:
                        if not isinstance(p, str) or p in RESERVED or re.fullmatch(r'-?\d+', p): raise ValueError("lambda param")
                        names.append(p)
                    if len(names) != len(set(names)): raise ValueError("lambda distinct names")
                    validate(body)
                elif head == 'if':
                    if len(ast) != 4: raise ValueError("if syntax")
                    for branch in ast[1:]:
                        if not isinstance(branch, (int, str, list)): raise ValueError("if branch")
                        validate(branch)
