        a, b = args
        if b == 0: raise ZeroDivisionError("// by zero")
        return a // b
    def builtin_mod(*args):
        if len(args) != 2: raise ValueError("% requires 2 arguments")
        a, b = args
        if b == 0: raise ZeroDivisionError("% by zero")
        return a % b
    def builtin_lt(*args):
        if len(args) != 2: raise ValueError("< requires 2 arguments")
        return 1 if args[0] < args[1] else 0
    def builtin_eq(*args):
        if len(args) != 2: raise ValueError("=" requires 2 arguments")
        return 1 if args[0] == args[1] else 0
    def builtin_gt(*args):
        if len(args) != 2: raise ValueError("> requires 2 arguments")
        return 1 if args[0] > args[1] else 0
    def builtin_min(*args):
