                return env[ast]
            raise ValueError(f"Unbound symbol: {ast}")
        if isinstance(ast, list):
            head = ast[0]
            if isinstance(head, str):
                if head == 'let':
                    bindings, body = ast[1], ast[2]
                    bound_env = dict(env)
                    for name, expr in bindings:
                        bound_env[name] = eval_expr(expr, env)
                    return eval_expr(body, bound_env)
                elif head == 'let*':
                    bindings, body = ast[1], ast[2]
                    bound_env = dict(env)
                    for name, expr in bindings:
                        bound_env[name] = eval_expr(expr, bound_env)
                    return eval_expr(body, bound_env)
                elif head == 'lambda':
                    return Closure(ast[1], ast[2], env)
                elif head == 'if':
                    test = eval_expr(ast[1], env)
                    if not isinstance(test, int):
                        raise ValueError("Test must be integer")
                    if test != 0:
                        return eval_expr(ast[2], env)
                    else:
