import re

def lisp_eval(src: str) -> int:
    """
    Evaluates a small Lisp expression.
    """
    if not src or not src.strip():
        raise ValueError("Empty input")

    # Tokenizer
    tokens = []
    i = 0
    n = len(src)
    while i < n:
        if src[i].isspace():
            i += 1
        elif src[i] in '()':
            tokens.append(src[i])
            i += 1
        else:
            j = i
            while j < n and src[j] not in ' \t\n\r()':
                j += 1
            tokens.append(src[i:j])
            i = j

    # Parser
    pos = 0
    def parse_expr():
        nonlocal pos
        if pos >= len(tokens):
            raise ValueError("Unexpected end of input")
        tok = tokens[pos]
        if tok == '(':
            pos += 1
            lst = []
            while True:
                if pos >= len(tokens):
                    raise ValueError("Unbalanced parentheses")
                if tokens[pos] == ')':
                    pos += 1
                    return lst
                lst.append(parse_expr())
        elif tok == ')':
            raise ValueError("Unbalanced parentheses")
        else:
            pos += 1
            if re.fullmatch(r'-?\d+', tok):
                return int(tok)
            return tok

    ast = parse_expr()
    if pos < len(tokens):
        raise ValueError("Trailing tokens after expression")

    # Validation
    RESERVED = {'let', 'let*', 'lambda', 'if'}

    def validate(ast):
        if isinstance(ast, list):
            if not ast:
                raise ValueError("Empty list")
            head = ast[0]
            if isinstance(head, str) and head in RESERVED:
                if head == 'let':
                    if len(ast) != 3: raise ValueError("let syntax")
                    bindings, body = ast[1], ast[2]
                    if not isinstance(bindings, list): raise ValueError("let bindings")
                    for b in bindings:
                        if not isinstance(b, list) or len(b) != 2: raise ValueError("let binding")
                        name, expr = b
                        if not isinstance(name, str) or name in RESERVED or re.fullmatch(r'-?\d+', name): raise ValueError("let name")
                        validate(expr)
                    names = [b[0] for b in bindings]
                    if len(names) != len(set(names)): raise ValueError("let distinct names")
                    validate(body)
                elif head == 'let*':
                    if len(ast) != 3: raise ValueError("let* syntax")
                    bindings, body = ast[1], ast[2]
                    if not isinstance(bindings, list): raise ValueError("let* bindings")
                    for b in bindings:
                        if not isinstance(b, list) or len(b) != 2: raise ValueError("let* binding")
                        name, expr = b
                        if not isinstance(name, str) or name in RESERVED or re.fullmatch(r'-?\d+', name): raise ValueError("let* name")
                        validate(expr)
                    validate(body)
                elif head == 'lambda':
                    if len(ast) != 3: raise ValueError("lambda syntax")
                    params, body = ast[1], ast[2]
                    if not isinstance(params, list): raise ValueError("lambda params")
                    names = []
                    for p in params:
                        if not isinstance(p, str) or p in RESERVED or re.fullmatch(r'-?\d+', p): raise ValueError("lambda param")
                        names.append(p)
                    if len(names) != len(set(names)): raise ValueError("lambda distinct names")
                    validate(body)
                elif head == 'if':
                    if len(ast) != 4: raise ValueError("if syntax")
                    for branch in ast[1:]:
                        validate(branch)
                else:
                    raise ValueError("reserved word")
            else:
                for item in ast:
                    validate(item)
        elif isinstance(ast, str):
            if ast in RESERVED:
                raise ValueError("reserved symbol as operand")
        elif isinstance(ast, int):
            pass
        else:
            raise ValueError("invalid type")

    validate(ast)

    # Built-in functions
    def make_builtin(func):
        func.is_builtin = True
        return func

    def builtin_add(*args): return sum(args)
    def builtin_mul(*args):
        res = 1
        for a in args: res *= a
        return res
    def builtin_sub(*args):
        if not args: raise ValueError("- requires arguments")
        if len(args) == 1: return -args[0]
        res = args[0]
        for a in args[1:]: res -= a
        return res
    def builtin_div(*args):
        if len(args) != 2: raise ValueError("// requires 2 arguments")
        a, b = args
        if b == 0: raise ZeroDivisionError("// by zero")
        return a // b
    def builtin_mod(*args):
        if len(args) != 2: raise ValueError("% requires 2 arguments")
        a, b = args
        if b == 0: raise ZeroDivisionError("% by zero")
        return a % b
    def builtin_lt(*args):
        if len(args) != 2: raise ValueError("< requires 2 arguments")
        return 1 if args[0] < args[1] else 0
    def builtin_eq(*args):
        if len(args) != 2: raise ValueError("= requires 2 arguments")
        return 1 if args[0] == args[1] else 0
    def builtin_gt(*args):
        if len(args) != 2: raise ValueError("> requires 2 arguments")
        return 1 if args[0] > args[1] else 0
    def builtin_min(*args):
        if not args: raise ValueError("min requires arguments")
        return min(args)
    def builtin_max(*args):
        if not args: raise ValueError("max requires arguments")
        return max(args)

    global_env = {
        '+': make_builtin(builtin_add),
        '*': make_builtin(builtin_mul),
        '-': make_builtin(builtin_sub),
        '//': make_builtin(builtin_div),
        '%': make_builtin(builtin_mod),
        '<': make_builtin(builtin_lt),
        '=': make_builtin(builtin_eq),
        '>': make_builtin(builtin_gt),
        'min': make_builtin(builtin_min),
        'max': make_builtin(builtin_max),
    }

    class Closure:
        def __init__(self, params, body, env):
            self.params = params
            self.body = body
            self.env = env
        def __call__(self, *args):
            if len(self.params) != len(args):
                raise ValueError("Arity mismatch")
            new_env = dict(self.env)
            for p, a in zip(self.params, args):
                new_env[p] = a
            return eval_expr(self.body, new_env)

    def eval_expr(ast, env):
        if isinstance(ast, int):
            return ast
        if isinstance(ast, str):
            if ast in env:
                return env[ast]
            raise ValueError(f"Unbound symbol: {ast}")
        if isinstance(ast, list):
            head = ast[0]
            if isinstance(head, str):
                if head == 'let':
                    bindings, body = ast[1], ast[2]
                    bound_env = dict(env)
                    for name, expr in bindings:
                        bound_env[name] = eval_expr(expr, env)
                    return eval_expr(body, bound_env)
                elif head == 'let*':
                    bindings, body = ast[1], ast[2]
                    bound_env = dict(env)
                    for name, expr in bindings:
                        bound_env[name] = eval_expr(expr, bound_env)
                    return eval_expr(body, bound_env)
                elif head == 'lambda':
                    return Closure(ast[1], ast[2], env)
                elif head == 'if':
                    test = eval_expr(ast[1], env)
                    if not isinstance(test, int):
                        raise ValueError("Test must be integer")
                    if test != 0:
                        return eval_expr(ast[2], env)
                    else:
                        return eval_expr(ast[3], env)

            f_val = eval_expr(head, env)
            args_vals = [eval_expr(a, env) for a in ast[1:]]

            if callable(f_val):
                if hasattr(f_val, 'is_builtin'):
                    for a in args_vals:
                        if not isinstance(a, int):
                            raise ValueError("Builtin expects integer")
                    return f_val(*args_vals)
                else:
                    return f_val(*args_vals)
            raise ValueError("Not a function")
        raise ValueError("Invalid expression")

    result = eval_expr(ast, global_env)
    if not isinstance(result, int):
        raise ValueError("Result must be integer")
    return result

import re

def render(template: str, ctx: dict) -> str:
    def validate_name(name):
        if not name:
            return False
        if name == '.':
            return True
        if name.startswith('.') or name.endswith('.'):
            return False
        if '..' in name:
            return False
        parts = name.split('.')
        for p in parts:
            if not re.match(r'^[A-Za-z0-9_]+$', p):
                return False
        return True

    def parse(template):
        nodes = []
        i = 0
        n = len(template)
        section_stack = []

        while i < n:
            if i + 1 < n and template[i] == '{' and template[i+1] == '{':
                if i + 2 < n and template[i+2] == '{':
                    end = template.find('}}}', i+3)
                    if end == -1:
                        raise ValueError("Unclosed triple tag")
                    content = template[i+3:end]
                    name = content.strip()
                    if not validate_name(name):
                        raise ValueError(f"Invalid name in triple tag: '{name}'")
                    nodes.append(('var', name, False))
                    i = end + 3
                else:
                    end = template.find('}}', i+2)
                    if end == -1:
                        raise ValueError("Unclosed double tag")
                    content = template[i+2:end]
                    if not content:
                        raise ValueError("Empty tag")
                    kind_char = content[0]
                    rest = content[1:].strip()

                    if kind_char == '#':
                        if not validate_name(rest):
                            raise ValueError(f"Invalid section name: '{rest}'")
                        sec = {'name': rest, 'kind': '#', 'nodes': []}
                        section_stack.append(sec)
                        nodes.append(sec)
                        i = end + 2
                    elif kind_char == '^':
                        if not validate_name(rest):
                            raise ValueError(f"Invalid section name: '{rest}'")
                        sec = {'name': rest, 'kind': '^', 'nodes': []}
                        section_stack.append(sec)
                        nodes.append(sec)
                        i = end + 2
                    elif kind_char == '/':
                        if not validate_name(rest):
                            raise ValueError(f"Invalid close name: '{rest}'")
                        if not section_stack:
                            raise ValueError("Close tag with no open section")
                        top = section_stack.pop()
                        if top['name'] != rest:
                            raise ValueError(f"Mismatched section: expected '{top['name']}', got '{rest}'")
                        i = end + 2
                    elif kind_char == '&':
                        if not validate_name(rest):
                            raise ValueError(f"Invalid variable name: '{rest}'")
                        nodes.append(('var', rest, False))
                        i = end + 2
                    elif kind_char == '!':
                        i = end + 2
                    else:
                        if not validate_name(rest):
                            raise ValueError(f"Invalid variable name: '{rest}'")
                        nodes.append(('var', rest, True))
                        i = end + 2
            else:
                next_tag = template.find('{{', i)
                if next_tag == -1:
                    text = template[i:]
                    if section_stack:
                        section_stack[-1]['nodes'].append(('text', text))
                    else:
                        nodes.append(('text', text))
                    i = n
                else:
                    text = template[i:next_tag]
                    if section_stack:
                        section_stack[-1]['nodes'].append(('text', text))
                    else:
                        nodes.append(('text', text))
                    i = next_tag

        if section_stack:
            raise ValueError("Unclosed section")
        return nodes

    def lookup(name, stack):
        if name == '.':
            return stack[0]

        parts = name.split('.')
        first = parts[0]
        val = None
        found = False

        for frame in stack:
            if isinstance(frame, dict) and first in frame:
                val = frame[first]
                found = True
                break

        if not found:
            return None

        for p in parts[1:]:
            if not isinstance(val, dict):
                return None
            if p in val:
                val = val[p]
            else:
                return None
        return val

    def value_to_text(val, escaped):
        if val is None:
            return ""
        if isinstance(val, bool):
            return "true" if val else "false"
        if isinstance(val, int):
            return str(val)
        if isinstance(val, str):
            if escaped:
                return (val.replace('&', '&amp;')
                        .replace('<', '&lt;')
                        .replace('>', '&gt;')
                        .replace('"', '&quot;')
                        .replace("'", '&#39;'))
            return val
        if isinstance(val, (list, dict)):
            raise ValueError("List or dict cannot be rendered as variable")
        raise ValueError(f"Unsupported type for variable: {type(val)}")

    def is_falsy(val):
        if val is None:
            return True
        if isinstance(val, bool):
            return not val
        if isinstance(val, (int, float)):
            return val == 0
        if isinstance(val, str):
            return val == ""
        if isinstance(val, (list, dict)):
            return len(val) == 0
        return False

    def render_nodes(nodes, stack):
        result = []
        for node in nodes:
            if node[0] == 'text':
                result.append(node[1])
            elif node[0] == 'var':
                name, escaped = node[1], node[2]
                val = lookup(name, stack)
                result.append(value_to_text(val, escaped))
            elif node[0] == 'section':
                name, kind, sec_nodes = node['name'], node['kind'], node['nodes']
                val = lookup(name, stack)
                if kind == '#':
                    if is_falsy(val):
                        continue
                    if isinstance(val, list):
                        for item in val:
                            result.append("".join(render_nodes(sec_nodes, [item] + stack)))
                    else:
                        result.append("".join(render_nodes(sec_nodes, [val] + stack)))
                elif kind == '^':
                    if is_falsy(val):
                        result.append("".join(render_nodes(sec_nodes, stack)))
        return result

    parsed = parse(template)
    return "".join(render_nodes(parsed, [ctx]))

