                raise ValueError("Unexpected end of data in varint")
            b = data[pos]
            pos += 1
            value |= (b & 0x7F) << (7 * i)
            if not (b & 0x80):
                break
        else:
            raise ValueError("Varint too long")
        if value >= 1 << 64:
            raise ValueError("Varint too large")
        return value

    while pos < len(data):
        key = read_varint()
        if key >= 1 << 32:
            raise ValueError("Key too large")
        field_number = key >> 3
        if field_number < 1:
            raise ValueError("Field number must be >= 1")
        wire_type = key & 7

        if wire_type == 0:
            value = read_varint()
            results.append((field_number, 0, value))
        elif wire_type == 1:
            if pos + 8 > len(data):
                raise ValueError("Not enough bytes for 64-bit value")
            value = int.from_bytes(data[pos:pos+8], 'little', signed=False)
            pos += 8
            results.append((field_number, 1, value))
        elif wire_type == 5:
            if pos + 4 > len(data):
                raise ValueError("Not enough bytes for 32-bit value")
            value = int.from_bytes(data[pos:pos+4], 'little', signed=False)
            pos += 4
            results.append((field_number, 5, value))
        elif wire_type == 2:
            length = read_varint()
            if pos + length > len(data):
                raise ValueError("Not enough bytes for length-prefixed value")
            value = data[pos:pos+length]
            pos += length
            results.append((field_number, 2, value))
        elif wire_type == 3:
            group_stack.append({'field_number': field_number, 'items': []})
        elif wire_type == 4:
            if not group_stack:
                raise ValueError("Unexpected end group")
            group = group_stack.pop()
            if group['field_number'] != field_number:
                raise ValueError("End group field number mismatch")
            target_list = group_stack[-1]['items'] if group_stack else results
            target_list.append((field_number, 3, group['items']))
        elif wire_type in (6, 7):
            raise ValueError(f"Unsupported wire type {wire_type}")
        else:
            raise ValueError(f"Unknown wire type {wire_type}")

    if group_stack:
        raise ValueError("Unterminated group")

    return results

def decode_fields(data: bytes) -> list:
    pos = 0
    results = []
    group_stack = []  # Stack of dicts: {'field_number': int, 'items': list}

    def read_varint():
        nonlocal pos
        value = 0
        for i in range(10):
            if pos >= len(data):
                raise ValueError("Unexpected end of data in varint")
            b = data[pos]
            pos += 1
            value |= (b & 0x7F) << (7 * i)
            if not (b & 0x80):
                break
        else:
            # Loop finished without break, meaning 10 bytes were read and the last one had 0x80 set
            raise ValueError("Varint too long")

        if value >= 1 << 64:
            raise ValueError("Varint too large")
        return value

    while pos < len(data):
        key = read_varint()

        if key >= 1 << 32:
            raise ValueError("Key too large")

        field_number = key >> 3
        if field_number < 1:
            raise ValueError("Field number must be >= 1")

        wire_type = key & 7

        if wire_type == 0:
            value = read_varint()
            item = (field_number, 0, value)
            if group_stack:
                group_stack[-1]['items'].append(item)
            else:
                results.append(item)

        elif wire_type == 1:
            if pos + 8 > len(data):
                raise ValueError("Not enough bytes for 64-bit value")
            value = int.from_bytes(data[pos:pos+8], 'little', signed=False)
            pos += 8
            item = (field_number, 1, value)
            if group_stack:
                group_stack[-1]['items'].append(item)
            else:
                results.append(item)

        elif wire_type == 5:
            if pos + 4 > len(data):
                raise ValueError("Not enough bytes for 32-bit value")
            value = int.from_bytes(data[pos:pos+4], 'little', signed=False)
            pos += 4
            item = (field_number, 5, value)
            if group_stack:
                group_stack[-1]['items'].append(item)
            else:
                results.append(item)

        elif wire_type == 2:
            length = read_varint()
            if pos + length > len(data):
                raise ValueError("Not enough bytes for length-prefixed value")
            value = data[pos:pos+length]
            pos += length
            item = (field_number, 2, value)
            if group_stack:
                group_stack[-1]['items'].append(item)
            else:
                results.append(item)

        elif wire_type == 3:
            group_stack.append({'field_number': field_number, 'items': []})

        elif wire_type == 4:
            if not group_stack:
                raise ValueError("Unexpected end group")
            group = group_stack.pop()
            if group['field_number'] != field_number:
                raise ValueError("End group field number mismatch")
            # The group tuple is added to the parent group's items (or results)
            # Since we just popped, the current top of stack is the parent.
            target_list = group_stack[-1]['items'] if group_stack else results
            target_list.append((field_number, 3, group['items']))

        elif wire_type in (6, 7):
            raise ValueError(f"Unsupported wire type {wire_type}")
        else:
            raise ValueError(f"Unknown wire type {wire_type}")

    if group_stack:
        raise ValueError("Unterminated group")

    return results

def strftime(fmt: str, dt: tuple) -> str:
    # Unpack date components
    if len(dt) != 6:
        raise ValueError("dt must be a tuple of 6 integers (year, month, day, hour, minute, second)")

    year, month, day, hour, minute, second = dt

    # Validation: Year
    if not (1 <= year <= 9999):
        raise ValueError(f"Year out of range: {year}")

    # Validation: Month
    if not (1 <= month <= 12):
        raise ValueError(f"Month out of range: {month}")

    # Validation: Day
    # Helper to check leap year
    def is_leap(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_in_month(y, m):
        days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if m == 2 and is_leap(y):
            return 29
        return days[m - 1]

    max_day = days_in_month(year, month)
    if not (1 <= day <= max_day):
        raise ValueError(f"Day out of range: {day} (max {max_day})")

    # Validation: Time
    if not (0 <= hour <= 23):
        raise ValueError(f"Hour out of range: {hour}")
    if not (0 <= minute <= 59):
        raise ValueError(f"Minute out of range: {minute}")
    if not (0 <= second <= 59):
        raise ValueError(f"Second out of range: {second}")

    # Helper functions for calculations
    def get_weekday(y, m, d):
        # Sakamoto's algorithm
        # Returns 0=Sunday, 1=Monday, ..., 6=Saturday
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        if m < 3:
            y -= 1
        return (y + y // 4 - y // 100 + y // 400 + t[m - 1] + d) % 7

    def get_day_of_year(y, m, d):
        doy = 0
        for i in range(1, m):
            doy += days_in_month(y, i)
        doy += d
        return doy

    def get_week_U(y, m, d):
        # Weeks start on Sunday. Week 00 for days before first Sunday.
        w_jan1 = get_weekday(y, 1, 1) # 0=Sun
        # First Sunday day of year
        # If Jan 1 is Sun (0), first Sun is day 1.
        # If Jan 1 is Mon (1), first Sun is day 7.
        # Offset from Jan 1 to first Sunday: (7 - w_jan1) % 7
        first_sun_doy = 1 + (7 - w_jan1) % 7

        doy = get_day_of_year(y, m, d)

        if doy < first_sun_doy:
            return 0
        return (doy - first_sun_doy) // 7 + 1

    def get_week_W(y, m, d):
        # Weeks start on Monday. Week 00 for days before first Monday.
        w_jan1 = get_weekday(y, 1, 1) # 0=Sun, 1=Mon
        # First Monday day of year
        # If Jan 1 is Mon (1), first Mon is day 1.
        # If Jan 1 is Sun (0), first Mon is day 2.
        # Offset from Jan 1 to first Monday: (1 - w_jan1) % 7
        first_mon_doy = 1 + (1 - w_jan1) % 7

        doy = get_day_of_year(y, m, d)

        if doy < first_mon_doy:
            return 0
        return (doy - first_mon_doy) // 7 + 1

    # Constants
    WEEKDAY_ABBR = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]
    WEEKDAY_FULL = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"]
    MONTH_ABBR = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    MONTH_FULL = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"]

    result = []
    i = 0
    n = len(fmt)

    while i < n:
        char = fmt[i]
        if char != '%':
            result.append(char)
            i += 1
        else:
            # Check for trailing %
            if i + 1 >= n:
                raise ValueError("Trailing '%' in format string")

            directive = fmt[i+1]
            next_i = i + 2

            if directive == '%':
                result.append('%')
            elif directive == 'Y':
                result.append(f"{year:04d}")
            elif directive == 'y':
                result.append(f"{year % 100:02d}")
            elif directive == 'm':
                result.append(f"{month:02d}")
            elif directive == 'd':
                result.append(f"{day:02d}")
            elif directive == 'e':
                result.append(f"{day:2d}")
            elif directive == 'H':
                result.append(f"{hour:02d}")
            elif directive == 'I':
                h12 = hour % 12
                if h12 == 0:
                    h12 = 12
                result.append(f"{h12:02d}")
            elif directive == 'p':
                result.append("AM" if hour < 12 else "PM")
            elif directive == 'M':
                result.append(f"{minute:02d}")
            elif directive == 'S':
                result.append(f"{second:02d}")
            elif directive == 'j':
                result.append(f"{get_day_of_year(year, month, day):03d}")
            elif directive == 'a':
                w = get_weekday(year, month, day)
                result.append(WEEKDAY_ABBR[w])
            elif directive == 'A':
                w = get_weekday(year, month, day)
                result.append(WEEKDAY_FULL[w])
            elif directive == 'b':
                result.append(MONTH_ABBR[month - 1])
            elif directive == 'B':
                result.append(MONTH_FULL[month - 1])
            elif directive == 'w':
                w = get_weekday(year, month, day)
                result.append(str(w))
            elif directive == 'u':
                w = get_weekday(year, month, day)
                # 1=Mon, 7=Sun. My w: 0=Sun, 1=Mon...
                # 0 -> 7, 1 -> 1, 2 -> 2 ...
                u_val = w if w != 0 else 7
                result.append(str(u_val))
            elif directive == 'U':
                result.append(f"{get_week_U(year, month, day):02d}")
            elif directive == 'W':
                result.append(f"{get_week_W(year, month, day):02d}")
            else:
                raise ValueError(f"Invalid directive '%{directive}'")

            i = next_i

    return "".join(result)

def bdecode(data: bytes):
    if not isinstance(data, bytes):
        raise TypeError("Input must be bytes")
    if not data:
        raise ValueError("Empty input")
    val, idx = _decode_value(data, 0)
    if idx != len(data):
        raise ValueError("Trailing bytes or unexpected byte")
    return val

def _decode_value(data, idx):
    if idx >= len(data):
        raise ValueError("Unexpected end of data")
    b = data[idx]
    if b == ord('i'):
        return _decode_int(data, idx)
    elif b == ord('l'):
        return _decode_list(data, idx)
    elif b == ord('d'):
        return _decode_dict(data, idx)
    elif ord('0') <= b <= ord('9'):
        return _decode_bytes(data, idx)
    else:
        raise ValueError(f"Unexpected byte {b}")

def _decode_bytes(data, idx):
    start = idx
    while idx < len(data) and data[idx] != ord(':'):
        idx += 1
    if idx >= len(data):
        raise ValueError("No colon found for byte string")
    length_str = data[start:idx]
    if len(length_str) == 0:
        raise ValueError("Empty length in byte string")
    if len(length_str) > 1 and length_str[0] == ord('0'):
        raise ValueError("Leading zeros in byte string length")
    length = int(length_str)
    idx += 1
    if idx + length > len(data):
        raise ValueError("Not enough bytes for byte string")
    result = data[idx:idx+length]
    return result, idx + length

def _decode_int(data, idx):
    idx += 1
    negative = False
    if idx < len(data) and data[idx] == ord('-'):
        negative = True
        idx += 1
    if idx >= len(data) or data[idx] == ord('e'):
        raise ValueError("Empty digits in integer")
    start = idx
    while idx < len(data) and data[idx] != ord('e'):
        if not (ord('0') <= data[idx] <= ord('9')):
            raise ValueError("Invalid character in integer")
        idx += 1
    if idx >= len(data):
        raise ValueError("No 'e' found for integer")
    num_str = data[start:idx]
    if len(num_str) > 1 and num_str[0] == ord('0'):
        raise ValueError("Leading zeros in integer")
    if negative and num_str == b'0':
        raise ValueError("Negative zero")
    val = int(num_str)
    if negative:
        val = -val
    idx += 1
    return val, idx

def _decode_list(data, idx):
    idx += 1
    result = []
    while idx < len(data) and data[idx] != ord('e'):
        val, idx = _decode_value(data, idx)
        result.append(val)
    if idx >= len(data):
        raise ValueError("No 'e' found for list")
    idx += 1
    return result, idx

def _decode_dict(data, idx):
    idx += 1
    result = {}
    last_key = None
    while idx < len(data) and data[idx] != ord('e'):
        key, idx = _decode_value(data, idx)
        if not isinstance(key, bytes):
            raise ValueError("Dict keys must be byte strings")
        if last_key is not None and key <= last_key:
            raise ValueError("Dict keys not strictly increasing")
        last_key = key
        val, idx = _decode_value(data, idx)
        result[key] = val
    if idx >= len(data):
        raise ValueError("No 'e' found for dict")
    idx += 1
    return result, idx

def bencode(obj) -> bytes:
    if isinstance(obj, bool):
        raise TypeError("bool is not allowed")
    if isinstance(obj, int):
        return _encode_int(obj)
    if isinstance(obj, bytes):
        return _encode_bytes(obj)
    if isinstance(obj, str):
        return _encode_bytes(obj.encode('utf-8'))
    if isinstance(obj, (list, tuple)):
        return _encode_list(obj)
    if isinstance(obj, dict):
        return _encode_dict(obj)
    raise TypeError(f"Unsupported type: {type(obj)}")

def _encode_int(n):
    return f"i{n}e".encode('ascii')

def _encode_bytes(b):
    return f"{len(b)}:".encode('ascii') + b

def _encode_list(seq):
    res = b"l"
    for item in seq:
        res += bencode(item)
    res += b"e"
    return res

def _encode_dict(d):
    encoded_keys = {}
    for k in d:
        if isinstance(k, bytes):
            ek = k
        elif isinstance(k, str):
            ek = k.encode('utf-8')
        else:
            raise TypeError(f"Dict key must be bytes or str, got {type(k)}")
        if ek in encoded_keys:
            raise ValueError(f"Duplicate encoded key: {ek}")
        encoded_keys[ek] = d[k]

    sorted_keys = sorted(encoded_keys.keys())

    res = b"d"
    for ek in sorted_keys:
        res += _encode_bytes(ek)
        res += bencode(encoded_keys[ek])
    res += b"e"
    return res

import sys

# Increase recursion depth just in case, though 20 is small.
sys.setrecursionlimit(2000)

def count_and_kth(lo: int, hi: int, m: int, k: int) -> tuple[int, int | None]:
    # Memoization table for DP states when tight is False
    # Key: (digits_remaining, prev_digit, current_sum_mod)
    # Value: count of valid completions
    # prev_digit: -1 if no digit placed yet (leading zeros state), 0-9 otherwise
    memo = {}

    def dp(rem: int, prev: int, s_mod: int) -> int:
        """
        Counts valid suffixes of length 'rem' given the previous digit 'prev'
        and current digit sum modulo 'm' is 's_mod'.
        Assumes we are not tight (can place any digit 0-9).
        """
        state = (rem, prev, s_mod)
        if state in memo:
            return memo[state]

        if rem == 0:
            # Base case: no digits left to place.
            # If we are still in leading zeros state (prev == -1), it means the number is 0.
            # 0 is good if 0 % m == 0 (always true for m >= 1).
            # If we have placed digits (prev != -1), we check if total sum is divisible by m.
            # Note: s_mod is the sum of digits placed so far.
            if prev == -1:
                return 1 # Number 0 is valid
            else:
                return 1 if s_mod == 0 else 0

        total = 0
        limit = 9
        for d in range(limit + 1):
            new_prev = d
            new_s_mod = s_mod

            # Check adjacency constraint
            # If prev == -1, we are placing leading zeros or starting the number.
            # Adjacency check only applies if we have already started the number (prev != -1).
            if prev != -1:
                if d == prev:
                    continue # Adjacent equal digits

            # Update state
            if prev == -1:
                if d == 0:
                    # Still in leading zeros
                    new_prev = -1
                    new_s_mod = 0 # Sum doesn't change for leading zeros
                else:
                    # Starting the number
                    new_prev = d
                    new_s_mod = (0 + d) % m
            else:
                # Already started
                new_prev = d
                new_s_mod = (s_mod + d) % m

            total += dp(rem - 1, new_prev, new_s_mod)

        memo[state] = total
        return total

    def count_upto(n: int) -> int:
        """Counts good integers in [0, n]."""
        if n < 0:
            return 0
        if n == 0:
            return 1 # 0 is good

        digits = list(map(int, str(n)))
        L = len(digits)

        # Memoization for tight states within this call
        memo_tight = {}

        def dp_tight(idx: int, tight: bool, prev: int, s_mod: int) -> int:
            if idx == L:
                if prev == -1:
                    return 1 # Number 0
                else:
                    return 1 if s_mod == 0 else 0

            # Optimization: if not tight, use the precomputed memo
            if not tight:
                rem = L - idx
                return dp(rem, prev, s_mod)

            state = (idx, tight, prev, s_mod)
            if state in memo_tight:
                return memo_tight[state]

            limit = digits[idx] if tight else 9
            res = 0

            for d in range(limit + 1):
                new_tight = tight and (d == limit)
                new_prev = d
                new_s_mod = s_mod

                if prev != -1:
                    if d == prev:
                        continue

                if prev == -1:
                    if d == 0:
                        new_prev = -1
                        new_s_mod = 0
                    else:
                        new_prev = d
                        new_s_mod = d % m
                else:
                    new_prev = d
                    new_s_mod = (s_mod + d) % m

                res += dp_tight(idx + 1, new_tight, new_prev, new_s_mod)

            memo_tight[state] = res
            return res

        return dp_tight(0, True, -1, 0)

    # Precompute memo for tight=False states
    # We can trigger it by calling dp with a large rem, or let it fill lazily.
    # Since m is constant, memo is valid.
    # We call count_upto(hi) first to populate memo for lengths up to len(str(hi)).

    count_hi = count_upto(hi)
    count_lo = count_upto(lo - 1)

    c = count_hi - count_lo

    if c < k:
        return (c, None)

    # Find k-th smallest good integer in [lo, hi]
    # This is the (count_lo + k)-th good integer in [0, hi].
    target_rank = count_lo + k

    # Binary search for the smallest x in [lo, hi] such that count_upto(x) >= target_rank
    low = lo
    high = hi
    ans = None

    while low <= high:
        mid = (low + high) // 2
        cnt = count_upto(mid)
        if cnt >= target_rank:
            ans = mid
            high = mid - 1
        else:
            low = mid + 1

    return (c, ans)

import sys
from bisect import bisect_left, bisect_right

def persistent_multiset(ops: list[tuple]) -> list[int | None]:
    sys.setrecursionlimit(2000)

    # Collect all values that will ever be added or removed
    vals_set = set()
    for op in ops:
        if op[0] in ('add', 'remove'):
            vals_set.add(op[2])

    vals = sorted(vals_set)
    M = len(vals)

    # If no values are ever added, all versions remain empty
    if M == 0:
        res = []
        for op in ops:
            if op[0] == 'kth':
                res.append(None)
            elif op[0] == 'count':
                res.append(0)
        return res

    val_to_rank = {v: i for i, v in enumerate(vals)}

    # Persistent segment tree arrays
    # Each update creates ~log2(M) new nodes. M <= 100,000, ops <= 100,000.
    # Safe upper bound: 3,000,000 nodes.
    MAX_NODES = 3_000_000
    L = [0] * MAX_NODES
    R = [0] * MAX_NODES
    cnt = [0] * MAX_NODES
    ptr = 1

    roots = [0] * (len(ops) + 1)  # roots[i] stores root of version i

    def update(old_node, l, r, idx, delta):
        nonlocal ptr
        new_node = ptr
        ptr += 1
        L[new_node] = L[old_node]
        R[new_node] = R[old_node]
        cnt[new_node] = cnt[old_node] + delta

        if l != r:
            mid = (l + r) // 2
            if idx <= mid:
                L[new_node] = update(L[old_node], l, mid, idx, delta)
            else:
                R[new_node] = update(R[old_node], mid + 1, r, idx, delta)
        return new_node

    def query_kth(node, l, r, k):
        if node == 0 or cnt[node] < k:
            return -1
        if l == r:
            return l
        mid = (l + r) // 2
        left_cnt = cnt[L[node]] if L[node] else 0
        if k <= left_cnt:
            return query_kth(L[node], l, mid, k)
        else:
            return query_kth(R[node], mid + 1, r, k - left_cnt)

    def query_count(node, l, r, ql, qr):
        if node == 0 or ql > r or qr < l:
            return 0
        if ql <= l and r <= qr:
            return cnt[node]
        mid = (l + r) // 2
        return query_count(L[node], l, mid, ql, qr) + query_count(R[node], mid + 1, r, ql, qr)

    version_count = 0
    res = []

    for op in ops:
        op_type = op[0]
        if op_type == 'add':
            _, v, x = op
            rank = val_to_rank[x]
            roots[version_count + 1] = update(roots[v], 0, M - 1, rank, 1)
            version_count += 1
        elif op_type == 'remove':
            _, v, x = op
            rank = val_to_rank[x]
            # Only decrease count if x is actually present in this version
            cur_cnt = query_count(roots[v], 0, M - 1, rank, rank)
            if cur_cnt > 0:
                roots[version_count + 1] = update(roots[v], 0, M - 1, rank, -1)
            else:
                roots[version_count + 1] = roots[v]
            version_count += 1
        elif op_type == 'kth':
            _, v, k = op
            if k < 1:
                res.append(None)
            else:
                rank = query_kth(roots[v], 0, M - 1, k)
                res.append(vals[rank] if rank != -1 else None)
        elif op_type == 'count':
            _, v, a, b = op
            if a > b:
                res.append(0)
            else:
                l_rank = bisect_left(vals, a)
                r_rank = bisect_right(vals, b) - 1
                if l_rank > r_rank:
                    res.append(0)
                else:
                    res.append(query_count(roots[v], 0, M - 1, l_rank, r_rank))

    return res

import sys

def iso_classes(trees: list[tuple[int, list[tuple[int, int]]]]) -> list[list[int]]:
    shape_to_id = {}
    next_id = 0

    def get_id(children_tuple):
        nonlocal next_id
        if children_tuple in shape_to_id:
            return shape_to_id[children_tuple]
        shape_to_id[children_tuple] = next_id
        next_id += 1
        return next_id - 1

    results = {}

    for idx, (n, edges) in enumerate(trees):
        if n == 0:
            continue

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Find centroids iteratively
        deg = [len(adj[i]) for i in range(n)]
        q = [i for i in range(n) if deg[i] == 1]
        rem = n
        centroids = []

        if n == 1:
            centroids = [0]
        else:
            while rem > 2:
                new_q = []
                for u in q:
                    rem -= 1
                    for v in adj[u]:
                        if deg[v] > 0:
                            deg[v] -= 1
                            if deg[v] == 1:
                                new_q.append(v)
                q = new_q
            centroids = q

        centroid_ids = []
        for root in centroids:
            # BFS to build traversal order and parent pointers
            parent = [-1] * n
            order = []
            stack = [root]
            visited = [False] * n
            visited[root] = True

            head = 0
            while head < len(stack):
                u = stack[head]
                head += 1
                order.append(u)
                for v in adj[u]:
                    if not visited[v]:
                        visited[v] = True
                        parent[v] = u
                        stack.append(v)

            # Process nodes bottom-up (leaves to root)
            node_ids = [0] * n
            for u in reversed(order):
                children = []
                for v in adj[u]:
                    if v != parent[u]:
                        children.append(node_ids[v])
                children.sort()
                node_ids[u] = get_id(tuple(children))

            centroid_ids.append(node_ids[root])

        centroid_ids.sort()
        sig = tuple(centroid_ids)

        if sig not in results:
            results[sig] = []
        results[sig].append(idx)

    # Format output: each class sorted, classes sorted by first index
    sorted_classes = [sorted(indices) for indices in results.values()]
    sorted_classes.sort(key=lambda x: x[0])
    return sorted_classes

import random

def mod_sqrts(a: int, m: int) -> list[int]:
    if m < 1:
        raise ValueError("m must be >= 1")
    if m == 1:
        return [0]

    a %= m

    # Factorize m
    factors = {}
    d = 2
    temp = m
    limit = int(temp**0.5) + 1
    while d <= limit and temp > 1:
        if temp % d == 0:
            count = 0
            while temp % d == 0:
                temp //= d
                count += 1
            factors[d] = count
            limit = int(temp**0.5) + 1
        d += 1 if d == 2 else 2

    if temp > 1:
        factors[temp] = 1

    prime_solutions = []
    for p, e in factors.items():
        pe = p ** e
        if p == 2:
            roots = _solve_mod_2(a, e)
        else:
            roots = _solve_mod_odd_prime(a, p, e)

        if not roots:
            return []
        prime_solutions.append((pe, roots))

    if not prime_solutions:
        return []

    current_mod, current_roots = prime_solutions[0]
    for i in range(1, len(prime_solutions)):
        next_mod, next_roots = prime_solutions[i]
        new_roots = []
        for r1 in current_roots:
            for r2 in next_roots:
                diff = (r2 - r1) % next_mod
                inv = pow(current_mod, -1, next_mod)
                k = (diff * inv) % next_mod
                x = (r1 + current_mod * k) % (current_mod * next_mod)
                new_roots.append(x)
        current_roots = new_roots
        current_mod *= next_mod

    current_roots.sort()
    return current_roots

def _solve_mod_2(a: int, e: int) -> list[int]:
    if e == 1:
        return [a % 2]
    if e == 2:
        return [x for x in range(4) if (x*x) % 4 == a]

    if a % 8 != 1:
        return []

    r = 1
    for k in range(3, e):
        diff = (r*r - a) // (1 << k)
        t = (-diff) & 1
        r += t * (1 << (k-1))

    r_mod = r % (1 << e)
    m = 1 << e
    roots = {r_mod, m - r_mod, (r_mod + (m >> 1)) % m, (m - r_mod + (m >> 1)) % m}
    return sorted(list(roots))

def _solve_mod_odd_prime(a: int, p: int, e: int) -> list[int]:
    if a == 0:
        k = (e + 1) // 2
        step = p ** k
        limit = p ** (e - k)
        return [i * step for i in range(limit)]

    v = 0
    temp_a = a
    while temp_a % p == 0:
        temp_a //= p
        v += 1

    if v % 2 == 1:
        return []

    if v > 0:
        new_e = e - v
        roots = _solve_mod_odd_prime_unit(temp_a, p, new_e)
        factor = p ** (v // 2)
        m = p ** e
        return sorted([(r * factor) % m for r in roots])
    else:
        return _solve_mod_odd_prime_unit(a, p, e)

def _solve_mod_odd_prime_unit(a: int, p: int, e: int) -> list[int]:
    if e == 1:
        r = _tonelli_shanks(a, p)
        if r is None:
            return []
        return [r, p - r]

    r0 = _tonelli_shanks(a, p)
    if r0 is None:
        return []

    r = r0
    pe = p
    for k in range(1, e):
        # Lift from p^k to p^(k+1)
        # r^2 = a (mod p^k)
        # r' = r + t * p^k
        # (r + t p^k)^2 = r^2 + 2 r t p^k = a (mod p^(k+1))
        # r^2 - a = c p^k
        # c + 2 r t = 0 (mod p)
        # t = -c * (2r)^-1 (mod p)
        diff = (r*r - a) // pe
        c = diff % p
        inv = pow((2 * r) % p, -1, p)
        t = (-c * inv) % p
        r += t * pe
        pe *= p

    m = p ** e
    return sorted([r % m, (m - (r % m)) % m])

def _tonelli_shanks(n: int, p: int) -> int:
    if pow(n, (p - 1) // 2, p) != 1:
        return None
    if p % 4 == 3:
        return pow(n, (p + 1) // 4, p)

    S = p - 1
    R = 0
    while S % 2 == 0:
        S //= 2
        R += 1

    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    M = R
    c = pow(z, S, p)
    t = pow(n, S, p)
    R_val = pow(n, (S + 1) // 2, p)

    while t != 1:
        i = 0
        temp = t
        while temp != 1:
            temp = pow(temp, 2, p)
            i += 1
            if i == M:
                return None # Should not happen

        b = pow(c, 1 << (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R_val = (R_val * b) % p

    return R_val

import math

def mod_sqrts(a: int, m: int) -> list[int]:
    """
    Returns a sorted list of all integers x such that 0 <= x < m and x*x == a (mod m).
    """
    if m < 1:
        raise ValueError("Modulus m must be >= 1")
    if m == 1:
        return [0]

    a = a % m

    # Factorize m into prime powers
    factors = []
    d = 2
    temp = m
    while d * d <= temp:
        if temp % d == 0:
            e = 0
            while temp % d == 0:
                e += 1
                temp //= d
            factors.append((d, e))
        d += 1
    if temp > 1:
        factors.append((temp, 1))

    # Solve for each prime power and combine using CRT
    # Store roots as (remainder, modulus) tuples
    all_roots = [(0, 1)]
    current_mod = 1

    for p, e in factors:
        p_pow = p ** e
        roots_p = _solve_prime_power(a, p, e)
        if not roots_p:
            return []

        # Combine with existing roots using CRT
        new_roots = []
        # Precompute inverse for CRT: current_mod^{-1} mod p_pow
        # Since p is a new prime factor, gcd(current_mod, p_pow) = 1
        try:
            inv = pow(current_mod, -1, p_pow)
        except ValueError:
            return []

        for rem1, mod1 in all_roots:
            for r2 in roots_p:
                # We want x = rem1 + mod1 * k such that x = r2 (mod p_pow)
                # rem1 + mod1 * k = r2 (mod p_pow)
                # mod1 * k = r2 - rem1 (mod p_pow)
                # k = (r2 - rem1) * inv (mod p_pow)
                k = ((r2 - rem1) * inv) % p_pow
                new_r = rem1 + mod1 * k
                new_roots.append((new_r, mod1 * p_pow))

        all_roots = new_roots
        current_mod *= p_pow

    return sorted([r[0] for r in all_roots])

def _solve_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e)"""
    n = p ** e
    a = a % n

    if p == 2:
        return _solve_mod_2pow(a, e)
    else:
        return _solve_mod_odd_prime_power(a, p, e)

def _solve_mod_2pow(a: int, e: int) -> list[int]:
    """Solves x^2 = a (mod 2^e)"""
    if e == 1:
        return [a % 2]

    if e == 2:
        if a % 4 == 0: return [0, 2]
        if a % 4 == 1: return [1, 3]
        return []

    # e >= 3
    # Check if a is a quadratic residue mod 8 if a is odd
    if a % 2 != 0:
        if a % 8 != 1:
            return []
        # Find one root using Hensel lifting from mod 8 to mod 2^e
        # Start with root x=1 mod 8 (since 1^2 = 1 = a mod 8)
        x = 1

        # Lift from 2^k to 2^{k+1} for k = 3 to e-1
        # We maintain x such that x^2 = a mod 2^k
        # We want to find t in {0, 1} such that (x + t*2^{k-1})^2 = a mod 2^{k+1}
        # (x + t*2^{k-1})^2 = x^2 + t*x*2^k + t^2*2^{2k-2}
        # Since k >= 3, 2k-2 >= k+1, so t^2 term vanishes mod 2^{k+1}
        # We need x^2 + t*x*2^k = a mod 2^{k+1}
        # t*x*2^k = a - x^2 mod 2^{k+1}
        # t*x = (a - x^2)/2^k mod 2
        # Since x is odd, x^{-1} mod 2 is 1.
        # t = (a - x^2)/2^k mod 2

        for k in range(3, e):
            # x is root mod 2^k. Check bit k of (a - x^2).
            # (a - x^2) must be divisible by 2^k.
            diff = (a - x * x) >> k
            t = diff & 1
            x += t << (k - 1)

        # Now x is a root mod 2^e.
        # The roots come in pairs x and -x, and also x + 2^{e-1} and -x + 2^{e-1}
        # Actually for 2^e (e>=3), there are 4 roots: x, -x, x+2^{e-1}, -x+2^{e-1}
        n = 1 << e
        r1 = x
        r2 = n - x
        r3 = (x + (1 << (e - 1))) % n
        r4 = (n - x + (1 << (e - 1))) % n

        roots = sorted({r1, r2, r3, r4})
        return roots
    else:
        # a is even. Let a = 2^k * u where u is odd.
        # If k is odd, no solution.
        # If k >= e, x^2 = 0 mod 2^e => x is multiple of 2^{ceil(e/2)}
        # If k < e and k is even (k=2j), then x = 2^j * y, y^2 = u mod 2^{e-2j}.

        # Count factors of 2 in a
        if a == 0:
            k = e
        else:
            k = 0
            temp = a
            while temp % 2 == 0:
                k += 1
                temp //= 2

        if k % 2 != 0:
            return []

        if k >= e:
            # x^2 = 0 mod 2^e
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        # k < e and k is even
        j = k // 2
        rem_e = e - k
        u = a >> k # a / 2^k

        # Solve y^2 = u mod 2^rem_e
        # u is odd
        roots_y = _solve_mod_2pow(u, rem_e)
        if not roots_y:
            return []

        shift = 1 << j
        return sorted([(r * shift) % (1 << e) for r in roots_y])

def _solve_mod_odd_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e) for odd prime p"""
    n = p ** e

    # Check if a is divisible by p
    if a % p == 0:
        # x^2 = 0 mod p^e implies x is multiple of p^ceil(e/2)
        # More generally, if a = p^k * u with p not dividing u.
        # If k is odd, no solution.
        # If k is even, x = p^{k/2} * y, y^2 = u mod p^{e-k}.

        k = 0
        temp = a
        while temp % p == 0:
            k += 1
            temp //= p

        if k % 2 != 0:
            return []

        half_k = k // 2
        rem_e = e - k

        if rem_e <= 0:
            # a = 0 mod p^e
            # x^2 = 0 mod p^e => x is multiple of p^ceil(e/2)
            limit = p ** ((e + 1) // 2)
            return list(range(0, p**e, limit))

        # Recursive step
        roots_y = _solve_mod_odd_prime_power(temp, p, rem_e)
        if not roots_y:
            return []

        shift = p ** half_k
        return sorted([(r * shift) % (p**e) for r in roots_y])

    # a is coprime to p
    # Solve x^2 = a mod p using Tonelli-Shanks
    roots_p = tonelli_shanks(a, p)
    if not roots_p:
        return []

    # Lift roots to mod p^e
    all_roots = []
    for r in roots_p:
        roots_lifted = hensel_lift(r, a, p, e)
        all_roots.extend(roots_lifted)

    return sorted(all_roots)

def tonelli_shanks(n: int, p: int) -> list[int]:
    """Returns list of solutions to x^2 = n mod p, or empty list."""
    n = n % p
    if n == 0:
        return [0]
    if p == 2:
        return [n]

    # Check Legendre symbol
    if pow(n, (p - 1) // 2, p) != 1:
        return []

    # Factor p-1 = Q * 2^S
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    # Find quadratic non-residue z
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    M = S
    c = pow(z, Q, p)
    t = pow(n, Q, p)
    R = pow(n, (Q + 1) // 2, p)

    while True:
        if t == 1:
            return [R, p - R]

        # Find smallest i, 0 < i < M, such that t^{2^i} = 1
        i = 1
        temp = t
        while i < M:
            temp = pow(temp, 2, p)
            if temp == 1:
                break
            i += 1

        if i == M:
            return []

        # b = c^{2^{M-i-1}}
        b = pow(c, 1 << (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

def hensel_lift(x0: int, a: int, p: int, e: int) -> list[int]:
    """Lifts solution x0 of x^2 = a mod p to mod p^e"""
    x = x0
    for k in range(1, e):
        # We have x^2 = a mod p^k
        # We want x_new = x + t * p^k mod p^{k+1}
        # (x + t p^k)^2 = x^2 + 2 x t p^k + t^2 p^{2k}
        # 2k >= k+1 for k >= 1.
        # So x^2 + 2 x t p^k = a mod p^{k+1}
        # 2 x t p^k = a - x^2 mod p^{k+1}
        # t = (a - x^2) / (2 x p^k) mod p

        # Compute numerator (a - x^2) / p^k
        num = (a - x * x) // (p ** k)

        # Denominator is 2*x mod p. Since x is root mod p, x != 0 mod p.
        inv_2x = pow((2 * x) % p, -1, p)
        t = (num * inv_2x) % p
        x += t * (p ** k)

    return [x % (p ** e)]

import math

def sqrt_cf(n: int) -> tuple[int, list[int]]:
    """
    Returns the continued fraction of sqrt(n) for an integer n >= 0 as (a0, period),
    where period is the shortest repeating block of partial quotients after a0.
    For a perfect square it is (isqrt(n), []). n < 0 raises ValueError.
    """
    if n < 0:
        raise ValueError("n must be non-negative")

    if n == 0:
        return (0, [])

    a0 = math.isqrt(n)
    if a0 * a0 == n:
        return (a0, [])

    # Algorithm to find period of continued fraction of sqrt(n)
    # m_0 = 0, d_0 = 1, a_0 = floor(sqrt(n))
    # m_{k+1} = d_k * a_k - m_k
    # d_{k+1} = (n - m_{k+1}^2) / d_k
    # a_{k+1} = floor((a_0 + m_{k+1}) / d_{k+1})
    # Period ends when d_k = 1 (or a_k = 2*a_0)

    m = 0
    d = 1
    a = a0
    period = []

    while True:
        m = d * a - m
        d = (n - m * m) // d
        a = (a0 + m) // d
        period.append(a)

        # The period ends when d becomes 1. 
        # At this point a should be 2*a0.
        if d == 1:
            break

    return (a0, period)

def pell(n: int, c: int) -> tuple[int, int] | None:
    """
    Returns the solution of x*x - n*y*y == c in positive integers x, y with the smallest y,
    or None if there is no such solution.
    c must be 1 or -1, and n must be a positive integer that is not a perfect square.
    """
    if c not in (1, -1):
        raise ValueError("c must be 1 or -1")
    if n <= 0:
        raise ValueError("n must be a positive integer")

    # Check if n is a perfect square
    if math.isqrt(n) ** 2 == n:
        raise ValueError("n must not be a perfect square")

    # Get continued fraction expansion
    a0, period = sqrt_cf(n)
    L = len(period)

    # Determine the index k of the convergent p_k/q_k that yields the solution
    # If c = -1: solution exists only if L is odd. k = L - 1.
    # If c = 1: 
    #   If L is even, k = L - 1.
    #   If L is odd, k = 2*L - 1.

    if c == -1:
        if L % 2 == 0:
            return None
        k = L - 1
    else: # c == 1
        if L % 2 == 0:
            k = L - 1
        else:
            k = 2 * L - 1

    # Compute convergent p_k / q_k
    # Recurrence:
    # p_{-1} = 1, p_{-2} = 0
    # q_{-1} = 0, q_{-2} = 1
    # p_i = a_i * p_{i-1} + p_{i-2}
    # q_i = a_i * q_{i-1} + q_{i-2}

    p_prev2 = 0  # p_{-2}
    p_prev1 = 1  # p_{-1}
    q_prev2 = 1  # q_{-2}
    q_prev1 = 0  # q_{-1}

    # We need to iterate from i = 0 to k
    # a_0 is a0, a_i for i >= 1 is period[(i-1) % L]

    for i in range(k + 1):
        if i == 0:
            a = a0
        else:
            a = period[(i - 1) % L]

        p_curr = a * p_prev1 + p_prev2
        q_curr = a * q_prev1 + q_prev2

        # Shift
        p_prev2 = p_prev1
        p_prev1 = p_curr
        q_prev2 = q_prev1
        q_prev1 = q_curr

    return (p_curr, q_curr)

import fractions

def clip_area(subject, clip):
    if len(subject) < 3 or len(clip) < 3:
        raise ValueError("Polygons must have at least 3 vertices.")

    def polygon_area_signed(poly):
        s = 0
        n = len(poly)
        for i in range(n):
            s += poly[i][0]*poly[(i+1)%n][1] - poly[i][1]*poly[(i+1)%n][0]
        return s

    if polygon_area_signed(subject) == 0 or polygon_area_signed(clip) == 0:
        raise ValueError("Polygons must have non-zero area.")

    # Check convexity of clip
    n = len(clip)
    signs = []
    for i in range(n):
        A = clip[i]
        B = clip[(i+1)%n]
        C = clip[(i+2)%n]
        cross = (B[0]-A[0])*(C[1]-B[1]) - (B[1]-A[1])*(C[0]-B[0])
        if cross > 0:
            signs.append(1)
        elif cross < 0:
            signs.append(-1)

    if len(signs) > 0 and 1 in signs and -1 in signs:
        raise ValueError("Clip polygon is not convex.")

    # Ensure clip is CCW for consistent half-plane testing (interior to the left)
    if polygon_area_signed(clip) < 0:
        clip = clip[::-1]

    output_subject = subject
    for i in range(n):
        A = clip[i]
        B = clip[(i+1)%n]
        input_subject = output_subject
        output_subject = []
        if not input_subject:
            break

        for j in range(len(input_subject)):
            S = input_subject[j]
            E = input_subject[(j+1)%len(input_subject)]

            # Cross products relative to edge A->B: cross(B-A, P-A)
            d1 = (B[0]-A[0])*(S[1]-A[1]) - (B[1]-A[1])*(S[0]-A[0])
            d2 = (B[0]-A[0])*(E[1]-A[1]) - (B[1]-A[1])*(E[0]-A[0])

            S_inside = d1 >= 0
            E_inside = d2 >= 0

            if S_inside and E_inside:
                output_subject.append(E)
            elif S_inside and not E_inside:
                denom = d2 - d1
                t = fractions.Fraction(-d1, denom)
                output_subject.append((S[0] + t*(E[0]-S[0]), S[1] + t*(E[1]-S[1])))
            elif not S_inside and E_inside:
                denom = d2 - d1
                t = fractions.Fraction(-d1, denom)
                output_subject.append((S[0] + t*(E[0]-S[0]), S[1] + t*(E[1]-S[1])))
                output_subject.append(E)
            # else both outside: do nothing

    if len(output_subject) < 3:
        return fractions.Fraction(0)

    area_val = 0
    m = len(output_subject)
    for i in range(m):
        x1, y1 = output_subject[i]
        x2, y2 = output_subject[(i+1)%m]
        area_val += x1*y2 - x2*y1
    return fractions.Fraction(abs(area_val), 2)

def hist_add(date: str, days: int, switch: str) -> str:
    def parse_date_str(s):
        if not isinstance(s, str) or len(s) != 10 or s[4] != '-' or s[7] != '-':
            raise ValueError("Invalid format")
        try:
            y, m, d = int(s[:4]), int(s[5:7]), int(s[8:10])
        except ValueError:
            raise ValueError("Invalid format")
        if y == 0:
            raise ValueError("Year 0000 invalid")
        return y, m, d

    def days_in_month(m, y, is_gregorian):
        if m in (1, 3, 5, 7, 8, 10, 12): return 31
        if m in (4, 6, 9, 11): return 30
        if m == 2:
            if is_gregorian:
                return 29 if (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)) else 28
            else:
                return 29 if (y % 4 == 0) else 28
        return 0

    def is_valid_date(y, m, d, is_gregorian):
        if m < 1 or m > 12: return False
        if d < 1 or d > days_in_month(m, y, is_gregorian): return False
        return True

    def julian_to_abs(y, m, d):
