def hist_add(date: str, days: int, switch: str) -> str:
    MONTH_DAYS = [0, 0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334]

    def is_leap(y, is_greg):
        if is_greg:
            return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
        return y % 4 == 0

    def gregorian_ordinal(y, m, d):
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + MONTH_DAYS[m] + (1 if is_leap(y, True) and m > 2 else 0) + d

    def julian_ordinal(y, m, d):
        return 365*(y-1) + (y-1)//4 + MONTH_DAYS[m] + (1 if is_leap(y, False) and m > 2 else 0) + d

    def ordinal_to_date(ord_val, is_greg):
        y = (ord_val - 1) // 365 + 1
        days_before_y = 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 if is_greg else 365*(y-1) + (y-1)//4
        if days_before_y >= ord_val:
            y -= 1
            days_before_y = 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 if is_greg else 365*(y-1) + (y-1)//4
        rem = ord_val - days_before_y
        leap = is_leap(y, is_greg)
        days_in_months = [31, 29 if leap else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        m = 0
        for i, dim in enumerate(days_in_months):
            if rem <= dim:
                m = i + 1
                d = rem
                break
            rem -= dim
        return y, m, d

    def parse_date(s):
        if len(s) != 10 or s[4] != '-' or s[7] != '-':
            raise ValueError("Invalid format")
        try:
            y, m, d = int(s[:4]), int(s[5:7]), int(s[8:10])
        except ValueError:
            raise ValueError("Invalid format")
        if y < 1 or y > 9999 or m < 1 or m > 12 or d < 1:
            raise ValueError("Invalid date components")
        return y, m, d

    sw_y, sw_m, sw_d = parse_date(switch)
    switch_ord = gregorian_ordinal(sw_y, sw_m, sw_d)
    if switch_ord < gregorian_ordinal(1582, 10, 15) or switch_ord > gregorian_ordinal(1929, 12, 31):
        raise ValueError("Switch date out of range")

    y, m, d = parse_date(date)
    g_ord = gregorian_ordinal(y, m, d)
    j_ord = julian_ordinal(y, m, d)

    if g_ord >= switch_ord:
        cal_ord = g_ord
        is_greg_date = True
    elif j_ord < switch_ord:
        cal_ord = j_ord
        is_greg_date = False
    else:
        raise ValueError("Date falls in the calendar gap")

    max_d = 31 if m in (1,3,5,7,8,10,12) else 30 if m != 2 else 29 if is_leap(y, is_greg_date) else 28
    if d > max_d:
        raise ValueError("Invalid day for month/year")

    result_ord = cal_ord + days
    if result_ord < 1 or result_ord > gregorian_ordinal(9999, 12, 31):
        raise ValueError("Result out of valid year range")

    res_y, res_m, res_d = ordinal_to_date(result_ord, result_ord >= switch_ord)
    return f"{res_y:04d}-{res_m:02d}-{res_d:02d}"

def _is_leap_j(y: int) -> bool:
    return y % 4 == 0

def _is_leap_g(y: int) -> bool:
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

_DAYS = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

def _days_before_year_j(y: int) -> int:
    y -= 1
    return y * 365 + y // 4

def _days_before_year_g(y: int) -> int:
    y -= 1
    return y * 365 + y // 4 - y // 100 + y // 400

def _to_julian_ordinal(y: int, m: int, d: int) -> int:
    return _days_before_year_j(y) + _DAYS[m-1] + d + (1 if m > 2 and _is_leap_j(y) else 0)

def _to_gregorian_ordinal(y: int, m: int, d: int) -> int:
    return _days_before_year_g(y) + _DAYS[m-1] + d + (1 if m > 2 and _is_leap_g(y) else 0)

def _from_julian_ordinal(n: int):
    n -= 1
    y = (n * 400) // 146100
    if _days_before_year_j(y + 1) <= n:
        y += 1
    if _days_before_year_j(y) > n:
        y -= 1
    doy = n - _days_before_year_j(y)
    if m > 2 and _is_leap_j(y):
        doy -= 1
    m = 1
    while m <= 12:
        if doy <= _DAYS[m]:
            break
        doy -= _DAYS[m]
        m += 1
    if m > 2 and _is_leap_j(y):
        doy += 1
    return y, m, doy

def _from_gregorian_ordinal(n: int):
    n -= 1
    y = (n * 400) // 146097
    if _days_before_year_g(y + 1) <= n:
        y += 1
    if _days_before_year_g(y) > n:
        y -= 1
    doy = n - _days_before_year_g(y)
    if m > 2 and _is_leap_g(y):
        doy -= 1
    m = 1
    while m <= 12:
        if doy <= _DAYS[m]:
            break
        doy -= _DAYS[m]
        m += 1
    if m > 2 and _is_leap_g(y):
        doy += 1
    return y, m, doy

def _prev_gregorian_date(y: int, m: int, d: int):
    if m == 3:
        days_feb = 29 if _is_leap_g(y) else 28
        return y, 2, days_feb
    if m in (4, 6, 9, 11):
        return y, m - 1, 30
    return y, m - 1, 31

def _parse_date(s: str):
    if len(s) != 10 or s[4] != '-' or s[7] != '-':
        raise ValueError("Invalid format")
    try:
        y, m, d = int(s[0:4]), int(s[5:7]), int(s[8:10])
    except ValueError:
        raise ValueError("Invalid format")
    if y < 1 or y > 9999:
        raise ValueError("Year out of range")
    return y, m, d

def _validate_date(y: int, m: int, d: int, is_greg: bool):
    if m < 1 or m > 12 or d < 1:
        return False
    days_in_month = _DAYS[m]
    if is_greg and _is_leap_g(y):
        if m == 2:
            days_in_month = 29
    elif not is_greg and _is_leap_j(y):
        if m == 2:
            days_in_month = 29
    return d <= days_in_month

def hist_add(date: str, days: int, switch: str) -> str:
    sy, sm, sd = _parse_date(switch)
    if not _validate_date(sy, sm, sd, True):
        raise ValueError("Invalid switch date")
    if (sy, sm, sd) < (1582, 10, 15) or (sy, sm, sd) > (1929, 12, 31):
        raise ValueError("Switch out of range")

    py, pm, pd = _prev_gregorian_date(sy, sm, sd)
    S = _to_gregorian_ordinal(sy, sm, sd)
    offset_j = _to_julian_ordinal(py, pm, pd) - (S - 1)

    dy, dm, dd = _parse_date(date)
    is_greg_date = (dy, dm, dd) >= (sy, sm, sd)

    if is_greg_date:
        if not _validate_date(dy, dm, dd, True):
            raise ValueError("Invalid date")
        if (dy, dm, dd) < (sy, sm, sd):
            raise ValueError("Date in gap")
        cont_date = _to_gregorian_ordinal(dy, dm, dd)
    else:
        if not _validate_date(dy, dm, dd, False):
            raise ValueError("Invalid date")
        if (dy, dm, dd) > (py, pm, pd):
            raise ValueError("Date in gap")
        cont_date = _to_julian_ordinal(dy, dm, dd) - offset_j

    cont_res = cont_date + days
    if cont_res < 1 or cont_res > _to_gregorian_ordinal(9999, 12, 31):
        raise ValueError("Result out of range")

    if cont_res >= S:
        ry, rm, rd = _from_gregorian_ordinal(cont_res)
        if not _validate_date(ry, rm, rd, True):
            raise ValueError("Invalid result")
    else:
        ry, rm, rd = _from_julian_ordinal(cont_res + offset_j)
        if not _validate_date(ry, rm, rd, False):
            raise ValueError("Invalid result")

    return f"{ry:04d}-{rm:02d}-{rd:02d}"

