def apportion(votes: List[int], seats: int, method: str, threshold: Tuple[int, int] = (0, 1)) -> List[int]:
    # Input validation
    for v in votes:
        if v < 0:
            raise ValueError("Vote count cannot be negative.")
    if seats < 0:
        raise ValueError("Seats cannot be negative.")

    num, den = threshold
    if num < 0 or den < 1:
        raise ValueError("Threshold num must be >= 0 and den must be >= 1.")

    valid_methods = {
        "dhondt", "sainte-lague", "modified-sainte-lague", 
        "huntington-hill", "hare", "droop"
    }
    if method not in valid_methods:
        raise ValueError(f"Unknown method: {method}")

    total_votes = sum(votes)

    # Determine eligible parties
    eligible_indices = []
    for i, v in enumerate(votes):
        if v > 0 and v * den >= num * total_votes:
            eligible_indices.append(i)

    if seats == 0:
        return [0] * len(votes)

    if not eligible_indices:
        raise ValueError("No eligible parties to apportion seats.")

    # Initialize result array
    result = [0] * len(votes)

    # Helper class for Highest-Averages methods to handle comparisons
    class Party:
        def __init__(self, idx: int, v: int, s: int, method: str):
            self.idx = idx
            self.v = v
            self.s = s
            self.method = method

        def get_divisor(self) -> Fraction:
            if self.method == "dhondt":
                return Fraction(self.s + 1)
            elif self.method == "sainte-lague":
                return Fraction(2 * self.s + 1)
            elif self.method == "modified-sainte-lague":
                if self.s == 0:
                    return Fraction(7, 5)
                else:
                    return Fraction(2 * self.s + 1)
            elif self.method == "huntington-hill":
                # For HH, we handle s=0 separately in logic, but if called here s >= 1
                return Fraction(math.sqrt(self.s * (self.s + 1)))
            return Fraction(1)

        def get_quotient(self) -> Fraction:
            if self.method == "huntington-hill":
                # For HH, comparison is v / sqrt(s(s+1))
                # To avoid float, we compare v1^2 * s2(s2+1) vs v2^2 * s1(s1+1)
                # But for heap storage, we need a comparable value.
                # We will use a custom comparison in __lt__
                return None 
            return Fraction(self.v, self.get_divisor())

        def __lt__(self, other):
            # We want the "best" party to be the "smallest" in the min-heap
            # Best = highest quotient, then highest votes, then lowest index

            # Compare quotients
            if self.method == "huntington-hill":
                # Compare v1 / sqrt(s1(s1+1)) vs v2 / sqrt(s2(s2+1))
                # Equivalent to v1^2 * s2(s2+1) vs v2^2 * s1(s1+1)
                lhs = self.v * self.v * other.s * (other.s + 1)
                rhs = other.v * other.v * self.s * (self.s + 1)
                if lhs != rhs:
                    return lhs > rhs  # Higher value is "smaller" (better)
            else:
                q1 = self.get_quotient()
                q2 = other.get_quotient()
                if q1 != q2:
                    return q1 > q2

            # Quotients equal, compare votes
            if self.v != other.v:
                return self.v > other.v

            # Votes equal, compare index
            return self.idx < other.idx

    if method in ["dhondt", "sainte-lague", "modified-sainte-lague", "huntington-hill"]:
        # Highest-Averages
        heap = []

        if method == "huntington-hill":
            # Special case: first every eligible party gets one seat
            if seats < len(eligible_indices):
                raise ValueError("Seats less than number of eligible parties for Huntington-Hill.")

            # Assign 1 seat to each
            for idx in eligible_indices:
                result[idx] = 1
                # Push to heap with s=1 (next divisor uses s=1)
                # Wait, D(s) is divisor for next seat given s seats held.
                # If party has 1 seat, next divisor is D(1) = sqrt(1*2).
                # So we push Party with s=1.
                heapq.heappush(heap, Party(idx, votes[idx], 1, method))

            remaining_seats = seats - len(eligible_indices)
        else:
            # Standard initialization
            for idx in eligible_indices:
                # Push with s=0 (next divisor D(0))
                heapq.heappush(heap, Party(idx, votes[idx], 0, method))
            remaining_seats = seats

        for _ in range(remaining_seats):
            if not heap:
                break # Should not happen if logic correct
            p = heapq.heappop(heap)
            result[p.idx] += 1
            p.s += 1
            # Push back with new s
            heapq.heappush(heap, p)

    elif method in ["hare", "droop"]:
        # Largest Remainder
        eligible_votes = [votes[i] for i in eligible_indices]
        V = sum(eligible_votes)

        if method == "hare":
            # Q = V / seats (exact rational)
            Q = Fraction(V, seats)
            # q_i = floor(votes_i / Q) = floor(votes_i * seats / V)
            # remainder = votes_i - q_i * Q
            # We can work with numerators to avoid fractions in sorting
            # remainder_i = votes_i - floor(votes_i * S / V) * (V / S)
            #             = (votes_i * S - floor(votes_i * S / V) * V) / S
            # Comparing remainders is comparing numerators: votes_i * S - q_i * V

            party_data = []
            for i in eligible_indices:
                v = votes[i]
                # Integer arithmetic for floor division
                # q = (v * seats) // V
                q = (v * seats) // V
                result[i] = q
                rem_num = v * seats - q * V
                party_data.append((i, v, rem_num))

            # Sort by remainder descending, then votes descending, then index ascending
            # Python sort is stable, but we need to define key
            # We want max rem_num, then max v, then min index
            # Sort key: (-rem_num, -v, index)
            party_data.sort(key=lambda x: (-x[2], -x[1], x[0]))

            assigned = sum(result[i] for i in eligible_indices)
            remaining = seats - assigned

            # Assign remaining seats
            # "If more seats remain than there are eligible parties, keep cycling"
            # But mathematically remaining < len(eligible_indices) usually.
            # Just iterate.
            idx_ptr = 0
            for _ in range(remaining):
                i = party_data[idx_ptr % len(party_data)][0]
                result[i] += 1
                idx_ptr += 1

        elif method == "droop":
            # Q = V // (seats + 1) + 1
            Q = V // (seats + 1) + 1
            party_data = []
            for i in eligible_indices:
                v = votes[i]
                q = v // Q
                result[i] = q
                rem = v - q * Q
                party_data.append((i, v, rem))

            # Sort by remainder descending, then votes descending, then index ascending
            party_data.sort(key=lambda x: (-x[2], -x[1], x[0]))

            assigned = sum(result[i] for i in eligible_indices)
            remaining = seats - assigned

            idx_ptr = 0
            for _ in range(remaining):
                i = party_data[idx_ptr % len(party_data)][0]
                result[i] += 1
                idx_ptr += 1

    return result

def monthly(start, count, interval=1, bymonthday=(), byday=(), bysetpos=(), until=None):
    if count < 0:
        raise ValueError("count must be >= 0")
    if interval < 1:
        raise ValueError("interval must be >= 1")

    def _parse_date(s):
        if not isinstance(s, str) or len(s) != 10 or s[4] != '-' or s[7] != '-':
            raise ValueError("start and until must be 'YYYY-MM-DD'")
        try:
            y, m, d = int(s[:4]), int(s[5:7]), int(s[8:10])
        except ValueError:
            raise ValueError("start and until must be 'YYYY-MM-DD'")
        if y < 1 or m < 1 or m > 12 or d < 1:
            raise ValueError("invalid date")
        return y, m, d

    start_y, start_m, start_d = _parse_date(start)
    until_y, until_m, until_d = None, None, None
    if until is not None:
        until_y, until_m, until_d = _parse_date(until)

    for v in bymonthday:
        if v == 0 or abs(v) > 31:
            raise ValueError("bymonthday values must be in -31..-1 or 1..31")

    for v in bysetpos:
        if v == 0 or abs(v) > 31:
            raise ValueError("bysetpos values must be in -31..-1 or 1..31")

    valid_days = {"MO", "TU", "WE", "TH", "FR", "SA", "SU"}
    for s in byday:
        if not isinstance(s, str) or len(s) < 2 or len(s) > 4:
            raise ValueError("malformed byday string")
        d_code = s[-2:]
        if d_code not in valid_days:
            raise ValueError("malformed byday string")
        ordinal_str = s[:-2]
        if ordinal_str != "":
            try:
                ord_val = int(ordinal_str)
            except ValueError:
                raise ValueError("malformed byday string")
            if ord_val == 0 or abs(ord_val) > 5:
                raise ValueError("byday ordinal must be in -5..5 excluding 0")

    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12): return 31
        if m in (4, 6, 9, 11): return 30
        return 29 if is_leap(y) else 28

    def dow(y, m, d):
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        if m < 3: y -= 1
        return (y + y // 4 - y // 100 + y // 400 + t[m - 1] + d) % 7

    day_map = {"MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6, "SU": 0}

    def parse_byday_entry(s):
        d_code = s[-2:]
        ordinal_str = s[:-2]
        if ordinal_str == "":
            return None, day_map[d_code]
        return int(ordinal_str), day_map[d_code]

    def get_days_for_byday(y, m, entries):
        days = []
        for ordinal, code in entries:
            month_days = [d for d in range(1, days_in_month(y, m) + 1) if dow(y, m, d) == code]
            if ordinal is None:
                days.extend(month_days)
            else:
                idx = ordinal - 1 if ordinal > 0 else len(month_days) + ordinal
                if 0 <= idx < len(month_days):
                    days.append(month_days[idx])
        return sorted(set(days))

    def get_days_for_bymonthday(y, m, days_list):
        res = []
        dim = days_in_month(y, m)
        for d in days_list:
            if d > 0:
                if 1 <= d <= dim: res.append(d)
            else:
                if -d <= dim: res.append(dim + d + 1)
        return sorted(set(res))

    def get_matching_days(y, m):
        days = []
        has_bmd = bool(bymonthday)
        has_byd = bool(byday)

        if has_bmd and has_byd:
            bmd_days = set(get_days_for_bymonthday(y, m, list(bymonthday)))
            byd_days = set(get_days_for_byday(y, m, [parse_byday_entry(s) for s in byday]))
            days = sorted(bmd_days & byd_days)
        elif has_bmd:
            days = get_days_for_bymonthday(y, m, list(bymonthday))
        elif has_byd:
            days = get_days_for_byday(y, m, [parse_byday_entry(s) for s in byday])
        else:
            d = start_d
            if 1 <= d <= days_in_month(y, m):
                days = [d]
            else:
                days = []

        if bysetpos:
            n = len(days)
            selected = set()
            for p in bysetpos:
                idx = p - 1 if p > 0 else n + p
                if 0 <= idx < n:
                    selected.add(days[idx])
            days = sorted(selected)
        return days

    if count == 0:
        return []

    results = []
    y, m = start_y, start_m

    while len(results) < count:
        if y > 9999:
            break

        matching_days = get_matching_days(y, m)

        for day in matching_days:
            if y == start_y and m == start_m and day < start_d:
                continue

            if until_y is not None:
                if y > until_y or (y == until_y and m > until_m) or (y == until_y and m == until_m and day > until_d):
                    return results

            results.append(f"{y:04d}-{m:02d}-{day:02d}")
            if len(results) == count:
                return results

        m += interval
        while m > 12:
            m -= 12
            y += 1

    return results

def monthly(start, count, interval=1, bymonthday=(), byday=(), bysetpos=(), until=None):
    if count < 0:
        raise ValueError("count must be >= 0")
    if interval < 1:
        raise ValueError("interval must be >= 1")

    def _parse_date(s):
        if not isinstance(s, str) or len(s) != 10 or s[4] != '-' or s[7] != '-':
            raise ValueError("start and until must be 'YYYY-MM-DD'")
        try:
            y, m, d = int(s[:4]), int(s[5:7]), int(s[8:10])
        except ValueError:
            raise ValueError("start and until must be 'YYYY-MM-DD'")
        if y < 1 or m < 1 or m > 12 or d < 1:
            raise ValueError("invalid date")

        # Check day validity for the specific month
        if m in (1, 3, 5, 7, 8, 10, 12):
            max_d = 31
        elif m in (4, 6, 9, 11):
            max_d = 30
        else: # February
            leap = (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0))
            max_d = 29 if leap else 28

        if d > max_d:
            raise ValueError("invalid date")

        return y, m, d

    start_y, start_m, start_d = _parse_date(start)
    until_y, until_m, until_d = None, None, None
    if until is not None:
        until_y, until_m, until_d = _parse_date(until)

    # Validate bymonthday
    for v in bymonthday:
        if not isinstance(v, int) or v == 0 or abs(v) > 31:
            raise ValueError("bymonthday values must be in -31..-1 or 1..31")

    # Validate bysetpos
    for v in bysetpos:
        if not isinstance(v, int) or v == 0 or abs(v) > 31:
            raise ValueError("bysetpos values must be in -31..-1 or 1..31")

    valid_days_codes = {"MO", "TU", "WE", "TH", "FR", "SA", "SU"}
    day_map = {"MO": 1, "TU": 2, "WE": 3, "TH": 4, "FR": 5, "SA": 6, "SU": 0}

    # Validate byday
    parsed_byday = []
    for s in byday:
        if not isinstance(s, str) or len(s) < 2 or len(s) > 4:
            raise ValueError("malformed byday string")
        d_code = s[-2:]
        if d_code not in valid_days_codes:
            raise ValueError("malformed byday string")
        ordinal_str = s[:-2]
        if ordinal_str == "":
            ordinal = None
        else:
            try:
                ordinal = int(ordinal_str)
            except ValueError:
                raise ValueError("malformed byday string")
            if ordinal == 0 or abs(ordinal) > 5:
                raise ValueError("byday ordinal must be in -5..5 excluding 0")
        parsed_byday.append((ordinal, day_map[d_code]))

    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)

    def days_in_month(y, m):
        if m in (1, 3, 5, 7, 8, 10, 12): return 31
        if m in (4, 6, 9, 11): return 30
        return 29 if is_leap(y) else 28

    def dow(y, m, d):
        # Returns 0 for Sunday, 1 for Monday, ..., 6 for Saturday
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        if m < 3: y -= 1
        return (y + y // 4 - y // 100 + y // 400 + t[m - 1] + d) % 7

    def get_days_for_byday(y, m, entries):
        days = []
        dim = days_in_month(y, m)
        for ordinal, code in entries:
            # Collect all days in month with this weekday
            month_days = [d for d in range(1, dim + 1) if dow(y, m, d) == code]
            if ordinal is None:
                days.extend(month_days)
            else:
                if ordinal > 0:
                    idx = ordinal - 1
                else:
                    idx = len(month_days) + ordinal
                if 0 <= idx < len(month_days):
                    days.append(month_days[idx])
        return sorted(set(days))

    def get_days_for_bymonthday(y, m, days_list):
        res = []
        dim = days_in_month(y, m)
        for d in days_list:
            if d > 0:
                if 1 <= d <= dim:
                    res.append(d)
            else:
                # Negative index: -1 is last day (dim)
                # Formula: dim + d + 1
                # Check validity: result must be >= 1
                # dim + d + 1 >= 1 => d >= -dim
                # Since d is negative, -d <= dim
                if -d <= dim:
                    res.append(dim + d + 1)
        return sorted(set(res))

    def get_matching_days(y, m):
        has_bmd = bool(bymonthday)
        has_byd = bool(byday)

        if has_bmd and has_byd:
            bmd_days = set(get_days_for_bymonthday(y, m, list(bymonthday)))
            byd_days = set(get_days_for_byday(y, m, parsed_byday))
            days = sorted(bmd_days & byd_days)
        elif has_bmd:
            days = get_days_for_bymonthday(y, m, list(bymonthday))
        elif has_byd:
            days = get_days_for_byday(y, m, parsed_byday)
        else:
            # Default: day of month of start
            if 1 <= start_d <= days_in_month(y, m):
                days = [start_d]
            else:
                days = []

        if bysetpos:
            n = len(days)
            selected = set()
            for p in bysetpos:
                idx = p - 1 if p > 0 else n + p
                if 0 <= idx < n:
                    selected.add(days[idx])
            days = sorted(selected)
        return days

    if count == 0:
        return []

    results = []
    y, m = start_y, start_m

    while len(results) < count:
        if y > 9999:
            break

        matching_days = get_matching_days(y, m)

        for day in matching_days:
            # Skip days before start date in the start month
            if y == start_y and m == start_m and day < start_d:
                continue

            # Check until constraint
            if until_y is not None:
                if y > until_y:
                    return results
                if y == until_y:
                    if m > until_m:
                        return results
                    if m == until_m:
                        if day > until_d:
                            return results

            results.append(f"{y:04d}-{m:02d}-{day:02d}")
            if len(results) == count:
                return results

        m += interval
        while m > 12:
            m -= 12
            y += 1

    return results
